"""# Rutina para Antonina

```
# Autor: Portilla Arcelia
```


"""

# ================================================================
# 2. IMPORTAR LIBRERÍAS Y CONFIGURAR GEE
# ================================================================
import ee
import geemap
import ipywidgets as widgets
from IPython.display import display, clear_output
import datetime

ee.Authenticate()
ee.Initialize(project='ee-arcelia-portilla')   # Cambia si tu proyecto es diferente

# ================================================================
# 3. CARGAR ASSETS (AOI Y COLECCIONES DE PUNTOS)
# ================================================================
aoi = ee.FeatureCollection('projects/ee-arcelia-portilla/assets/AOI_Paranagua').geometry()

antonina_raw = ee.FeatureCollection('projects/ee-arcelia-portilla/assets/Antonina')
braza_raw = ee.FeatureCollection('projects/ee-arcelia-portilla/assets/Braza')

# ================================================================
# FUNCIÓN PARA LIMPIAR Y CONVERTIR NÚMEROS (CORREGIDA)
# ================================================================
def limpiar_campo_numero(feature, campo):
    """
    Convierte un campo a número, reemplazando coma por punto.
    Si el campo no existe o es nulo, asigna -999.
    """
    # Verificar si la propiedad existe usando propertyNames().contains()
    tiene_campo = feature.propertyNames().contains(campo)

    def convertir():
        valor = feature.get(campo)
        valor_str = ee.String(valor)
        valor_str_clean = valor_str.replace(',', '.')
        patron = '^-?[0-9]+(\\.[0-9]+)?$'
        es_numero = valor_str_clean.match(patron)
        numero = ee.Algorithms.If(es_numero, ee.Number.parse(valor_str_clean), -999)
        return feature.set(campo, numero)

    def no_convertir():
        return feature.set(campo, -999)

    return ee.Algorithms.If(tiene_campo, convertir(), no_convertir())

# ================================================================
# PROCESAMIENTO DE BRAZA
# ================================================================
# Filtrar puntos con long/lat no nulos
braza_raw = braza_raw.filter(ee.Filter.notNull(['long', 'lat']))

# Crear geometría Point a partir de long/lat (convertir coma a punto)
braza = braza_raw.map(lambda f: ee.Feature(
    ee.Geometry.Point([
        ee.Number.parse(ee.String(f.get('long')).replace(',', '.')),
        ee.Number.parse(ee.String(f.get('lat')).replace(',', '.'))
    ]),
    f.toDictionary()
))

# Convertir campos numéricos a números (incluyendo long y lat)
campos_numericos_braza = ['depth_m', 'chla_ugL', 'secchi_m', 'turbidity_NTU', 'long', 'lat']
for campo in campos_numericos_braza:
    braza = braza.map(lambda f, c=campo: limpiar_campo_numero(f, c))

# ================================================================
# PROCESAMIENTO DE ANTONINA (usando geometría existente)
# ================================================================
# Solo convertimos Z1 a número; no modificamos geometría
antonina = antonina_raw.map(lambda f: limpiar_campo_numero(f, 'Z1'))

# ================================================================
# DICCIONARIO DE COLECCIONES
# ================================================================
colecciones = {
    'Antonina': {
        'fc': antonina,
        'campos': ['Z1'],                      # Solo exportar Z1 (coordenadas vienen de geometría)
        'campo_prof': 'Z1',
        'color': 'yellow',
        'campos_coord': []                     # Sin campos de respaldo; usaremos geometría
    },
    'Braza': {
        'fc': braza,
        'campos': ['station_name', 'long', 'lat', 'depth_m', 'chla_ugL', 'secchi_m', 'turbidity_NTU'],
        'campo_prof': 'depth_m',
        'color': 'red',
        'campos_coord': ['long', 'lat']        # Campos de respaldo (por si acaso)
    }
}

# ================================================================
# 4. FUNCIONES AUXILIARES
# ================================================================
def calc_indices(img):
    ndwi = img.normalizedDifference(['B3','B8']).rename('NDWI')
    agua = ndwi.gt(0.1)
    ndci = img.normalizedDifference(['B5','B4']).rename('NDCI').updateMask(agua)
    ndti = img.normalizedDifference(['B4','B3']).rename('NDTI').updateMask(agua)
    return img.addBands([ndwi, ndci, ndti])

def ajustar_offset_atmosferico(img, puntos_profundos):
    puntos_en_imagen = puntos_profundos.filterBounds(img.geometry())
    tiene_puntos = puntos_en_imagen.size().gt(0)
    bandas = ['B2','B3','B4','B5']
    stats = ee.Algorithms.If(
        tiene_puntos,
        img.select(bandas).reduceRegion(
            reducer=ee.Reducer.percentile([1]),
            geometry=puntos_en_imagen.geometry(),
            scale=10,
            maxPixels=1e13,
            bestEffort=True
        ),
        ee.Dictionary({})
    )
    stats = ee.Dictionary(stats)
    b2 = ee.Number(ee.Algorithms.If(stats.contains('B2_p1'), stats.get('B2_p1'), 0))
    b3 = ee.Number(ee.Algorithms.If(stats.contains('B3_p1'), stats.get('B3_p1'), 0))
    b4 = ee.Number(ee.Algorithms.If(stats.contains('B4_p1'), stats.get('B4_p1'), 0))
    b5 = ee.Number(ee.Algorithms.If(stats.contains('B5_p1'), stats.get('B5_p1'), 0))
    offset = ee.Image.constant([b2,b3,b4,b5]).rename(bandas)
    corregida = img.select(bandas).subtract(offset).max(0)
    return img.addBands(corregida, None, True)

def get_imagen_para_fecha(fecha, puntos_profundos):
    col = ee.ImageCollection('COPERNICUS/S2_HARMONIZED') \
            .filterBounds(aoi) \
            .filterDate(fecha, ee.Date(fecha).advance(1,'day')) \
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    img = col.first()
    if img is None:
        return None, None
    img = img.clip(aoi)
    img_corr = ajustar_offset_atmosferico(img, puntos_profundos)
    indices = calc_indices(img_corr)
    return img_corr, indices

def obtener_fechas_disponibles(start_date, end_date):
    col = ee.ImageCollection('COPERNICUS/S2_HARMONIZED') \
            .filterBounds(aoi) \
            .filterDate(start_date, end_date) \
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    fechas = col.aggregate_array('system:time_start') \
                .map(lambda t: ee.Date(t).format('YYYY-MM-dd')) \
                .distinct() \
                .getInfo()
    return sorted(fechas)

def exportar_csv(muestra, nombre_coleccion, fecha, campos):
    nombre_archivo = f"{nombre_coleccion}_{fecha.replace('-','')}"
    task = ee.batch.Export.table.toDrive(
        collection=muestra,
        description=nombre_archivo,
        folder='CSV_Antonina',
        fileFormat='CSV',
        selectors=campos
    )
    task.start()
    print(f"  → Exportación encolada: {nombre_archivo}.csv")

# ================================================================
# 5. VARIABLES GLOBALES DEL ESTADO
# ================================================================
fechas_lista = []
indice_actual = -1
fecha_actual = None
coleccion_actual = None
coleccion_info = None
puntos_aoi = None
puntos_profundos = None

# ================================================================
# 6. FUNCIONES DE INTERFAZ
# ================================================================
def cargar_fechas(b):
    global fechas_lista, indice_actual, fecha_actual, coleccion_actual, coleccion_info, puntos_aoi, puntos_profundos
    coleccion_actual = selector_coleccion.value
    coleccion_info = colecciones[coleccion_actual]
    puntos_aoi = coleccion_info['fc'].filterBounds(aoi)
    puntos_profundos = coleccion_info['fc'].filter(ee.Filter.lt(coleccion_info['campo_prof'], -20)).filterBounds(aoi)

    try:
        count_aoi = puntos_aoi.size().getInfo()
        count_prof = puntos_profundos.size().getInfo()
        print(f"Puntos dentro del AOI: {count_aoi}")
        print(f"Puntos profundos: {count_prof}")
    except Exception as e:
        print(f"Error al contar puntos: {e}")
        return

    start = fecha_inicio.value.strftime('%Y-%m-%d')
    end = fecha_fin.value.strftime('%Y-%m-%d')
    fechas_lista = obtener_fechas_disponibles(start, end)
    if fechas_lista:
        indice_actual = 0
        fecha_actual = fechas_lista[indice_actual]
        fecha_label.value = f"Fecha: {fecha_actual} ({indice_actual+1}/{len(fechas_lista)})"
        mostrar_mapa()
    else:
        fecha_label.value = "No hay fechas en el rango seleccionado."
        indice_actual = -1
        with map_output:
            clear_output()
            print("No hay imágenes disponibles.")

def mostrar_mapa():
    with map_output:
        clear_output()
        if fecha_actual is None:
            print("No hay fecha seleccionada.")
            return
        img, indices = get_imagen_para_fecha(fecha_actual, puntos_profundos)
        if img is None:
            print("No se pudo cargar la imagen para esta fecha.")
            return
        Map = geemap.Map()
        Map.centerObject(aoi, 11)
        Map.addLayer(img.select(['B4','B3','B2']), {'min':0,'max':3000}, 'RGB')
        Map.addLayer(indices.select('NDWI'), {'min':-0.5,'max':0.8,'palette':['white','cyan','blue']}, 'NDWI')
        Map.addLayer(indices.select('NDCI'), {'min':-1,'max':1,'palette':['0000ff','5bff08','fff80e','ffad18','ff0202']}, 'NDCI')
        Map.addLayer(indices.select('NDTI'), {'min':-1,'max':1,'palette':['0000ff','5bff08','fff80e','ffad18','ff0202']}, 'NDTI')
        Map.addLayer(puntos_aoi, {'color':coleccion_info['color'],'pointSize':3}, coleccion_actual)
        Map.addLayer(aoi, {'color':'red','fillColor':'00000000'}, 'AOI Paranaguá')
        display(Map)

def navegar(delta):
    global indice_actual, fecha_actual
    if not fechas_lista:
        return
    nuevo = indice_actual + delta
    if 0 <= nuevo < len(fechas_lista):
        indice_actual = nuevo
        fecha_actual = fechas_lista[indice_actual]
        fecha_label.value = f"Fecha: {fecha_actual} ({indice_actual+1}/{len(fechas_lista)})"
        mostrar_mapa()

# Función auxiliar para agregar campos de fecha y coordenadas
def agregar_campos(feature, img, fecha_str, campos_coord):
    """
    Extrae coordenadas de la geometría del feature.
    Si la geometría no es un punto válido, usa campos de respaldo si existen.
    """
    geom = feature.geometry()
    tiene_geom = ee.Algorithms.IsEqual(geom.type(), ee.String('Point'))

    # Intentar extraer coordenadas de la geometría
    lon = ee.Algorithms.If(tiene_geom, geom.coordinates().get(0), -999)
    lat = ee.Algorithms.If(tiene_geom, geom.coordinates().get(1), -999)

    # Si se proporcionan campos de respaldo y la geometría no es punto, usar esos campos
    if campos_coord and len(campos_coord) >= 2:
        lon_fallback = feature.get(campos_coord[0])
        lat_fallback = feature.get(campos_coord[1])
        lon = ee.Algorithms.If(tiene_geom, lon, lon_fallback)
        lat = ee.Algorithms.If(tiene_geom, lat, lat_fallback)

    return feature.set({
        'fecha': fecha_str,
        'datetime': ee.Date(img.get('system:time_start')).format('YYYY-MM-dd HH:mm:ss'),
        'hora': ee.Number(ee.Date(img.get('system:time_start')).get('hour'))
                 .add(ee.Number(ee.Date(img.get('system:time_start')).get('minute')).divide(60)),
        'lon': lon,
        'lat': lat
    })

def exportar_actual(b):
    if not fechas_lista or indice_actual == -1:
        print("Primero carga fechas y selecciona una fecha.")
        return
    img, indices = get_imagen_para_fecha(fecha_actual, puntos_profundos)
    if img is None:
        print("No se pudo obtener imagen.")
        return
    bandas = indices.select(['B2','B3','B4','B5','B8','NDWI','NDCI','NDTI'])
    muestra = bandas.sampleRegions(
        collection=puntos_aoi,
        scale=10,
        properties=coleccion_info['campos'],
        geometries=True   # Mantener geometría para extraer coordenadas
    )
    # Agregar campos adicionales (fecha, hora, coordenadas)
    muestra = muestra.map(lambda f: agregar_campos(f, img, fecha_actual, coleccion_info['campos_coord']))
    campos_export = coleccion_info['campos'] + ['fecha','datetime','hora','lon','lat','B2','B3','B4','B5','B8','NDWI','NDCI','NDTI']
    exportar_csv(muestra, coleccion_actual, fecha_actual, campos_export)

def exportar_todo(b):
    if not fechas_lista:
        print("Primero carga las fechas.")
        return
    print(f"Exportando {len(fechas_lista)} fechas...")
    for idx, fecha in enumerate(fechas_lista):
        print(f"Procesando {idx+1}/{len(fechas_lista)}: {fecha}")
        img, indices = get_imagen_para_fecha(fecha, puntos_profundos)
        if img is None:
            print(f"  → No hay imagen para {fecha}, omitiendo.")
            continue
        bandas = indices.select(['B2','B3','B4','B5','B8','NDWI','NDCI','NDTI'])
        muestra = bandas.sampleRegions(
            collection=puntos_aoi,
            scale=10,
            properties=coleccion_info['campos'],
            geometries=True
        )
        muestra = muestra.map(lambda f: agregar_campos(f, img, fecha, coleccion_info['campos_coord']))
        campos_export = coleccion_info['campos'] + ['fecha','datetime','hora','lon','lat','B2','B3','B4','B5','B8','NDWI','NDCI','NDTI']
        exportar_csv(muestra, coleccion_actual, fecha, campos_export)
    print("Todas las exportaciones han sido encoladas.")

# ================================================================
# 7. INTERFAZ DE USUARIO (WIDGETS)
# ================================================================
selector_coleccion = widgets.Dropdown(options=list(colecciones.keys()), description='Colección:')
fecha_inicio = widgets.DatePicker(description='Desde:', value=datetime.date(2016,1,1))
fecha_fin = widgets.DatePicker(description='Hasta:', value=datetime.date(2025,12,31))
btn_cargar = widgets.Button(description='Cargar fechas')
btn_anterior = widgets.Button(description='◀ Anterior')
btn_siguiente = widgets.Button(description='Siguiente ▶')
btn_exportar = widgets.Button(description='Exportar CSV')
btn_exportar_todo = widgets.Button(description='Exportar todas las fechas')
fecha_label = widgets.Label(value='No hay fechas cargadas')
map_output = widgets.Output()

btn_cargar.on_click(cargar_fechas)
btn_anterior.on_click(lambda x: navegar(-1))
btn_siguiente.on_click(lambda x: navegar(1))
btn_exportar.on_click(exportar_actual)
btn_exportar_todo.on_click(exportar_todo)

ui = widgets.VBox([
    widgets.HBox([selector_coleccion]),
    widgets.HBox([fecha_inicio, fecha_fin, btn_cargar]),
    widgets.HBox([btn_anterior, fecha_label, btn_siguiente]),
    widgets.HBox([btn_exportar, btn_exportar_todo]),
    map_output
])

display(ui)

"""# Correçao Mare

Modelo global de maré Adaptado de Egbert, Gary D., and Svetlana Y. Erofeeva. "Efficient inverse modeling of barotropic ocean tides." Journal of Atmospheric and Oceanic Technology 19.2 (2002): 183-204.
"""

import pandas as pd
import numpy as np
import xarray as xr
from datetime import datetime
import os
import glob
import re
from google.colab import drive
drive.mount('/content/drive')

import xarray as xr

arquivo_h = '/content/drive/MyDrive/Tesis_Final/DATA/h_tpxo10.v2.nc'
h_tpxo = xr.open_dataset(arquivo_h)

print("Dimensões:", list(h_tpxo.dims))
print("Coordenadas:", list(h_tpxo.coords))
print("Variáveis:", list(h_tpxo.data_vars))

# Verifique também as dimensões das variáveis 'ha' e 'hp'
print("\nDimensões de 'ha':", h_tpxo['ha'].dims)
print("Dimensões de 'hp':", h_tpxo['hp'].dims)

h_tpxo.close()

"""DELTA_PARANAGUA_LESTE = 0.958 # valor obtido da ficha F41 - Padrão - PORTO DE PARANAGUA - CAIS LESTE I - 60141
DELTA_PARANAGUA_BARRA = 0.794 # valor obtido da ficha F41 - Padrão - BARRA DE PARANAGUÁ - CANAL DA GALHETA -
DELTA_ANTONINA = 1.082 # valor obtido da ficha F41 - Padrão - ANTONINA - 60110 - Versão 1/2016

corregido marea rutina
"""

import numpy as np
import pandas as pd
import xarray as xr
import os, glob
from datetime import datetime
from scipy.interpolate import RegularGridInterpolator

# =====================================================
# CONFIGURACIONES
# =====================================================
pasta_csv = '/content/drive/MyDrive/Tesis_Final/CSV_Paranagua'
pasta_saida = '/content/drive/MyDrive/Tesis_Final/Paranagua_Corregida_v2'
os.makedirs(pasta_saida, exist_ok=True)

arquivo_h = '/content/drive/MyDrive/Tesis_Final/DATA/h_tpxo10.v2.nc'

pontos_delta = np.array([
    [-48.3167, -25.5667, 0.794],
    [-48.4950, -25.5000, 0.958],
    [-48.6933, -25.4433, 1.082],
])

# =====================================================
# FUNCIONES AUXILIARES
# =====================================================

def delta_idw(lon, lat, p=2):
    dx = lon[:, None] - pontos_delta[:, 0]
    dy = lat[:, None] - pontos_delta[:, 1]
    d = np.sqrt(dx**2 + dy**2)
    d[d < 1e-6] = 1e-6
    w = 1 / (d ** p)
    return np.sum(w * pontos_delta[:, 2], axis=1) / np.sum(w, axis=1)

def horas_desde_epoca(data_hora, epoca=datetime(1992, 1, 1)):
    delta = data_hora - epoca
    return delta.total_seconds() / 3600.0

def preparar_interpoladores(h_tpxo):
    lon_2d = h_tpxo['lon_z'].values
    lat_2d = h_tpxo['lat_z'].values

    lon_1d = np.unique(lon_2d)
    lat_1d = np.unique(lat_2d)
    if lat_1d[0] > lat_1d[-1]:
        lat_1d = lat_1d[::-1]
    lon_1d = lon_1d % 360
    lon_1d = np.sort(lon_1d)

    ha = h_tpxo['ha'].values
    hp = h_tpxo['hp'].values

    ha_reshaped = np.transpose(ha, (0, 2, 1))
    hp_reshaped = np.transpose(hp, (0, 2, 1))

    interp_ha = []
    interp_hp = []
    for k in range(ha_reshaped.shape[0]):
        interp_ha.append(RegularGridInterpolator((lat_1d, lon_1d), ha_reshaped[k],
                                                 bounds_error=False, fill_value=np.nan))
        interp_hp.append(RegularGridInterpolator((lat_1d, lon_1d), hp_reshaped[k],
                                                 bounds_error=False, fill_value=np.nan))

    if 'omega' in h_tpxo:
        omega = h_tpxo['omega'].values
    else:
        const_names = h_tpxo['con'].values.astype(str)
        vel_padrao = {
            'M2': 28.984104, 'S2': 30.0, 'N2': 28.439730, 'K2': 30.082138,
            'K1': 15.041069, 'O1': 13.943035, 'P1': 14.958931, 'Q1': 13.398661,
            'M4': 57.968208, 'MS4': 58.984104, 'MN4': 57.423834, 'M6': 86.952312,
            'S1': 15.0, 'M3': 43.476156, '2N2': 27.895354, 'L2': 29.528479,
            'MU2': 27.968208, 'NU2': 28.512583, 'MK3': 44.025173, 'M8': 115.936416
        }
        omega = np.array([vel_padrao.get(name, 0.0) for name in const_names])

    omega_rad = np.deg2rad(omega)

    return lon_1d, lat_1d, interp_ha, interp_hp, omega_rad

def calcular_mare(lon, lat, horas, lon_1d, lat_1d, interp_ha, interp_hp, omega_rad):
    lon = np.asarray(lon) % 360
    lat = np.asarray(lat)
    points = np.column_stack((lat, lon))

    eta = np.zeros(len(lon))
    for k in range(len(interp_ha)):
        H = interp_ha[k](points)
        fase = np.deg2rad(interp_hp[k](points))
        w = omega_rad[k]
        mask = ~np.isnan(H) & (H > 0)
        eta[mask] += H[mask] * np.cos(w * horas - fase[mask])

    return eta

def identificar_colunas(df):
    df.columns = df.columns.str.strip()

    lat_candidates = ['lat', 'latitude', 'Y']
    lon_candidates = ['lon', 'long', 'longitude', 'X']
    z_candidates = ['z', 'depth', 'profundidade', 'z1', 'Z1', 'depth_m']
    dt_candidates = ['datetime', 'date', 'fecha', 'hora']

    col_lat = None
    col_lon = None
    col_z = None
    col_dt = None

    for col in df.columns:
        col_low = col.lower()
        if col_low in lat_candidates and col_lat is None:
            col_lat = col
        elif col_low in lon_candidates and col_lon is None:
            col_lon = col
        elif col_low in z_candidates and col_z is None:
            col_z = col
        elif col_low in dt_candidates and col_dt is None:
            col_dt = col

    if col_dt is None:
        fecha_col = next((c for c in df.columns if c.lower() == 'fecha'), None)
        hora_col = next((c for c in df.columns if c.lower() == 'hora'), None)
        if fecha_col is not None and hora_col is not None:
            df['datetime'] = pd.to_datetime(df[fecha_col] + ' ' + df[hora_col].astype(str))
            col_dt = 'datetime'
        else:
            raise ValueError("Columna de fecha/hora no encontrada")

    if col_lat is None or col_lon is None or col_z is None:
        raise ValueError("Faltan columnas de lat/lon/z")

    return col_lat, col_lon, col_z, col_dt

def renomear_seguro(df, mapping):
    for old, new in mapping.items():
        if old == new:
            continue
        if new in df.columns and new != old:
            df.rename(columns={new: f"{new}_orig"}, inplace=True)
        df.rename(columns={old: new}, inplace=True)
    return df

def unificar_profundidad_positiva(df):
    """
    Convierte cualquier convencion de profundidad a valores positivos
    donde 0 = superficie, positivo = profundidad (metros hacia abajo)
    """
    valores_z = df['z'].values

    if np.all(valores_z >= 0):
        # Caso Braza: ya son positivos (profundidad desde superficie)
        df['z_positivo'] = valores_z.copy()
        df['convencion_original'] = 'positivo_braza'
        print("  Convencion detectada: Profundidad POSITIVA (Braza)")
        print("    Ejemplo: z=5.0 significa 5 metros de profundidad")

    elif np.all(valores_z <= 0):
        # Caso Antonina/Paranagua: negativos (superficie=0, profundo=negativo)
        df['z_positivo'] = -valores_z
        df['convencion_original'] = 'negativo_batimetria'
        print("  Convencion detectada: Profundidad NEGATIVA (Antonina/Paranagua)")
        print(f"    Ejemplo: z={valores_z[0]:.2f} -> profundidad positiva={df['z_positivo'].iloc[0]:.2f} metros")

    else:
        # Mezcla de signos (usar valor absoluto)
        print("  ADVERTENCIA: Mezcla de profundidades positivas y negativas")
        df['z_positivo'] = np.abs(valores_z)
        df['convencion_original'] = 'mixto'

    return df

def aplicar_correccion_marea_unificada(df):
    """
    Aplica correccion de marea usando profundidades positivas unificadas
    Ecuacion fisica: profundidad_corregida = profundidad_original + (eta - delta)
    """
    # Paso 1: Unificar a profundidad positiva
    df = unificar_profundidad_positiva(df)

    # Paso 2: Calcular correccion neta
    correccion_neta = df['eta_MSL'] - df['Delta']

    # Paso 3: Aplicar correccion en espacio positivo
    # Si marea alta (eta positivo): aumenta profundidad
    # Si marea baja (eta negativo): disminuye profundidad
    df['profundidad_corregida_positiva'] = df['z_positivo'] + correccion_neta

    # Paso 4: No permitir profundidades negativas (no puede haber profundidad < 0)
    df['profundidad_corregida_positiva'] = df['profundidad_corregida_positiva'].clip(lower=0)

    # Paso 5: Convertir de vuelta a la convencion original
    if df['convencion_original'].iloc[0] == 'negativo_batimetria':
        # Antonina/Paranagua: convertir a negativo
        df['Z_corrigido'] = -df['profundidad_corregida_positiva']
        df['z_original_positivo'] = -df['z']  # Para referencia
    else:
        # Braza: mantener positivo
        df['Z_corrigido'] = df['profundidad_corregida_positiva']
        df['z_original_positivo'] = df['z']

    # Diferencia en el espacio original
    df['dif'] = df['Z_corrigido'] - df['z']

    return df

def diagnosticar_correccion(df, eta, delta):
    """Diagnostico completo de la correccion"""
    print("\n" + "-" * 50)
    print("DIAGNOSTICO DE CORRECCION")
    print("-" * 50)

    correccion_neta = eta - delta

    print(f"\n1. PROFUNDIDAD ORIGINAL:")
    print(f"   Valor original (z): {df['z'].iloc[0]:.4f} m")
    print(f"   Convertido a positivo: {df['z_positivo'].iloc[0]:.4f} m")
    print(f"   Convencion: {df['convencion_original'].iloc[0]}")

    print(f"\n2. COMPONENTES DE MAREA:")
    print(f"   eta_MSL (altura de marea): {eta.mean():.4f} +/- {eta.std():.4f} m")
    print(f"   Delta (correccion espacial): {delta.mean():.4f} +/- {delta.std():.4f} m")
    print(f"   Correccion neta (eta - delta): {correccion_neta.mean():.4f} m")

    if correccion_neta.mean() > 0:
        print(f"   INTERPRETACION: Marea ALTA predominante -> AUMENTA profundidad")
    else:
        print(f"   INTERPRETACION: Marea BAJA predominante -> DISMINUYE profundidad")

    print(f"\n3. APLICACION DE ECUACION (en espacio positivo):")
    print(f"   profundidad_corregida = z_positivo + (eta - delta)")
    print(f"   = {df['z_positivo'].mean():.4f} + ({correccion_neta.mean():.4f})")
    print(f"   = {df['profundidad_corregida_positiva'].mean():.4f} m")

    print(f"\n4. RESULTADO FINAL (en convencion original):")
    print(f"   Z_corrigido medio: {df['Z_corrigido'].mean():.4f} m")
    print(f"   Cambio medio: {df['dif'].mean():+.4f} m")

    # Verificacion fisica
    print(f"\n5. VERIFICACION FISICA:")
    if df['convencion_original'].iloc[0] == 'negativo_batimetria':
        if correccion_neta.mean() > 0:
            print("   CORRECTO: Marea alta -> Z_corrigido MAS negativo (mas profundo)")
            expected = df['z'].mean() - abs(correccion_neta.mean())
            print(f"   Esperado: {df['z'].mean():.4f} -> {expected:.4f}")
            print(f"   Obtenido: {df['z'].mean():.4f} -> {df['Z_corrigido'].mean():.4f}")
        else:
            print("   CORRECTO: Marea baja -> Z_corrigido MENOS negativo (menos profundo)")
            expected = df['z'].mean() + abs(correccion_neta.mean())
            print(f"   Esperado: {df['z'].mean():.4f} -> {expected:.4f}")
            print(f"   Obtenido: {df['z'].mean():.4f} -> {df['Z_corrigido'].mean():.4f}")
    else:
        if correccion_neta.mean() > 0:
            print("   CORRECTO: Marea alta -> Z_corrigido MAYOR (mas profundo)")
        else:
            print("   CORRECTO: Marea baja -> Z_corrigido MENOR (menos profundo)")

    return correccion_neta

# =====================================================
# PROCESAMIENTO PRINCIPAL
# =====================================================

def processar():
    print("=" * 60)
    print("CORRECION DE MAREA - VERSION UNIFICADA")
    print("Todas las profundidades se convierten a positivo para el calculo")
    print("=" * 60)

    print("\nCargando datos TPXO...")
    h_tpxo = xr.open_dataset(arquivo_h)

    lon_1d, lat_1d, interp_ha, interp_hp, omega_rad = preparar_interpoladores(h_tpxo)
    print(f"Grade TPXO: {len(lon_1d)} longitudes x {len(lat_1d)} latitudes")
    print(f"Longitudes: {lon_1d.min():.2f} a {lon_1d.max():.2f}")
    print(f"Latitudes: {lat_1d.min():.2f} a {lat_1d.max():.2f}")

    arquivos = glob.glob(os.path.join(pasta_csv, "*.csv"))
    if not arquivos:
        print("No se encontraron archivos CSV.")
        return

    print(f"\nEncontrados {len(arquivos)} archivos.\n")
    resumo = []

    for arq in arquivos:
        nome = os.path.basename(arq)
        print(f"\n{'='*60}")
        print(f"Procesando: {nome}")
        print(f"{'='*60}")

        try:
            # Leer CSV
            try:
                df = pd.read_csv(arq, encoding='utf-8')
            except UnicodeDecodeError:
                df = pd.read_csv(arq, encoding='latin1')

            # Identificar columnas
            col_lat, col_lon, col_z, col_dt = identificar_colunas(df)

            # Renombrar
            mapping = {col_lat: 'lat', col_lon: 'lon', col_z: 'z', col_dt: 'datetime'}
            df = renomear_seguro(df, mapping)

            # Convertir datetime
            df['datetime'] = pd.to_datetime(df['datetime'], errors='coerce')
            df_valid = df.dropna(subset=['datetime'])

            if df_valid.empty:
                print("  Error: No hay fechas validas")
                continue

            data_hora = df_valid['datetime'].iloc[0]
            print(f"\nFecha/Hora: {data_hora}")

            # Horas desde epoca
            horas = horas_desde_epoca(data_hora)

            # Calcular marea para cada punto
            eta = calcular_mare(df['lon'].values, df['lat'].values, horas,
                                lon_1d, lat_1d, interp_ha, interp_hp, omega_rad)

            # Delta espacial (IDW)
            delta = delta_idw(df['lon'].values, df['lat'].values)

            # Agregar columnas
            df['eta_MSL'] = eta
            df['Delta'] = delta

            # APLICAR CORRECCION CON ESTRATEGIA UNIFICADA
            df = aplicar_correccion_marea_unificada(df)

            # Diagnosticar
            correccion_neta = diagnosticar_correccion(df, eta, delta)

            # Guardar resultado
            out_file = os.path.join(pasta_saida, nome.replace('.csv', '_corregido.csv'))
            df.to_csv(out_file, index=False)

            # Estadisticas resumen
            print(f"\nRESUMEN ESTADISTICO:")
            print(f"  Puntos procesados: {len(df)}")
            print(f"  Profundidad original: {df['z'].mean():.3f} +- {df['z'].std():.3f} m")
            print(f"  Profundidad corregida: {df['Z_corrigido'].mean():.3f} +- {df['Z_corrigido'].std():.3f} m")
            print(f"  Cambio medio: {df['dif'].mean():+.3f} m")
            print(f"  eta_MSL medio: {np.nanmean(eta):+.3f} m")
            print(f"  Delta medio: {np.nanmean(delta):+.3f} m")
            print(f"  Correccion neta media: {correccion_neta.mean():+.3f} m")

            # Verificar valores sobre superficie
            if df['convencion_original'].iloc[0] == 'negativo_batimetria':
                n_sobre_superficie = (df['Z_corrigido'] > 0).sum()
                if n_sobre_superficie > 0:
                    print(f"\n  ADVERTENCIA: {n_sobre_superficie} puntos quedaron sobre superficie (Z_corrigido > 0)")
                    print(f"  Porcentaje: {n_sobre_superficie/len(df)*100:.2f}%")

            resumo.append({
                'Arquivo': nome,
                'Data_Hora': data_hora,
                'Convencion': df['convencion_original'].iloc[0],
                'Eta_medio': np.nanmean(eta),
                'Delta_medio': np.nanmean(delta),
                'Correccion_neta_media': correccion_neta.mean(),
                'Correccion_aplicada_media': np.nanmean(df['dif']),
                'Prof_orig_media': np.nanmean(df['z']),
                'Prof_corr_media': np.nanmean(df['Z_corrigido']),
                'Num_pontos': len(df),
                'Puntos_sobre_superficie': (df['Z_corrigido'] > 0).sum() if df['convencion_original'].iloc[0] == 'negativo_batimetria' else 0
            })

        except Exception as e:
            print(f"  ERROR: {e}")
            import traceback
            traceback.print_exc()
            continue

    h_tpxo.close()

    if resumo:
        df_resumo = pd.DataFrame(resumo)
        df_resumo.to_csv(os.path.join(pasta_saida, 'resumo_correcoes.csv'), index=False)

        print("\n" + "=" * 60)
        print("RESUMEN FINAL DE CORRECCIONES")
        print("=" * 60)
        print(df_resumo.to_string())

        return df_resumo
    else:
        print("No se procesaron archivos.")
        return None

# =====================================================
# EJECUCION
# =====================================================
if __name__ == "__main__":
    df_resumo = processar()

"""rutina de marea antes de modificaciones"""

import numpy as np
import pandas as pd
import xarray as xr
import os, glob
from datetime import datetime
from scipy.interpolate import RegularGridInterpolator

# =====================================================
# CONFIGURAÇÕES, modificar conforme os dados  csv
# =====================================================
pasta_csv = '/content/drive/MyDrive/Tesis_Final/CSV_Antonina'
pasta_saida = '/content/drive/MyDrive/Tesis_Final/Antonina_Corregida'
os.makedirs(pasta_saida, exist_ok=True)

arquivo_h = '/content/drive/MyDrive/Tesis_Final/DATA/h_tpxo10.v2.nc'

pontos_delta = np.array([
    [-48.3167, -25.5667, 0.794],
    [-48.4950, -25.5000, 0.958],
    [-48.6933, -25.4433, 1.082],
])

# =====================================================
# FUNÇÕES AUXILIARES
# =====================================================

def delta_idw(lon, lat, p=2):
    dx = lon[:, None] - pontos_delta[:, 0]
    dy = lat[:, None] - pontos_delta[:, 1]
    d = np.sqrt(dx**2 + dy**2)
    d[d < 1e-6] = 1e-6
    w = 1 / (d ** p)
    return np.sum(w * pontos_delta[:, 2], axis=1) / np.sum(w, axis=1)

def horas_desde_epoca(data_hora, epoca=datetime(1992, 1, 1)):
    delta = data_hora - epoca
    return delta.total_seconds() / 3600.0

def preparar_interpoladores(h_tpxo):
    """
    Extrai as coordenadas únicas de longitude e latitude a partir das
    variáveis 2D lon_z e lat_z. Cria interpoladores regulares para cada
    constituinte.
    Retorna:
        lon_1d, lat_1d: arrays 1D com valores únicos de lon e lat
        interp_ha: lista de RegularGridInterpolator para amplitude
        interp_hp: lista de RegularGridInterpolator para fase
        omega_rad: array com velocidades angulares em rad/h
    """
    # Obter arrays 2D de longitude e latitude
    lon_2d = h_tpxo['lon_z'].values  # shape (nx, ny)
    lat_2d = h_tpxo['lat_z'].values  # shape (nx, ny)

    # Extrair valores únicos ordenados (assumindo grade regular)
    # TPXO tem grade regular, então os valores ao longo de cada eixo são constantes
    lon_1d = np.unique(lon_2d)       # deve ser monotônico
    lat_1d = np.unique(lat_2d)       # pode ser decrescente se latitude sul
    # Garantir ordem crescente para o interpolador
    if lat_1d[0] > lat_1d[-1]:
        lat_1d = lat_1d[::-1]
    # Também garantir que lon_1d esteja em [0,360)
    lon_1d = lon_1d % 360
    lon_1d = np.sort(lon_1d)

    # Obter amplitudes e fases
    ha = h_tpxo['ha'].values   # shape (nc, nx, ny)
    hp = h_tpxo['hp'].values   # shape (nc, nx, ny)

    # Reorganizar para (nc, ny, nx) se necessário (o interpolador espera (lat, lon))
    # Como queremos as dimensões (lat, lon), e nossos arrays estão (nx, ny),
    # vamos transpor para (ny, nx) e depois usar (lat_1d, lon_1d).
    ha_reshaped = np.transpose(ha, (0, 2, 1))   # (nc, ny, nx)
    hp_reshaped = np.transpose(hp, (0, 2, 1))

    # Criar interpoladores para cada constituinte
    interp_ha = []
    interp_hp = []
    for k in range(ha_reshaped.shape[0]):
        # Para grade regular, o interpolador espera (lat_1d, lon_1d)
        interp_ha.append(RegularGridInterpolator((lat_1d, lon_1d), ha_reshaped[k],
                                                 bounds_error=False, fill_value=np.nan))
        interp_hp.append(RegularGridInterpolator((lat_1d, lon_1d), hp_reshaped[k],
                                                 bounds_error=False, fill_value=np.nan))

    # Obter velocidades angulares (omega)
    if 'omega' in h_tpxo:
        omega = h_tpxo['omega'].values   # graus/hora
    else:
        # Usar dicionário padrão (velocidades dos principais constituintes)
        const_names = h_tpxo['con'].values.astype(str)
        vel_padrao = {
            'M2': 28.984104, 'S2': 30.0, 'N2': 28.439730, 'K2': 30.082138,
            'K1': 15.041069, 'O1': 13.943035, 'P1': 14.958931, 'Q1': 13.398661,
            'M4': 57.968208, 'MS4': 58.984104, 'MN4': 57.423834, 'M6': 86.952312,
            'S1': 15.0, 'M3': 43.476156, '2N2': 27.895354, 'L2': 29.528479,
            'MU2': 27.968208, 'NU2': 28.512583, 'MK3': 44.025173, 'M8': 115.936416
        }
        omega = np.array([vel_padrao.get(name, 0.0) for name in const_names])

    omega_rad = np.deg2rad(omega)   # rad/h

    return lon_1d, lat_1d, interp_ha, interp_hp, omega_rad

def calcular_mare(lon, lat, horas, lon_1d, lat_1d, interp_ha, interp_hp, omega_rad):
    """
    Calcula a altura da maré η_MSL para cada ponto (lon, lat) no instante `horas`.
    """
    # Normalizar longitude para [0,360)
    lon = np.asarray(lon) % 360
    lat = np.asarray(lat)

    # Pontos para interpolação (lat, lon)
    points = np.column_stack((lat, lon))

    eta = np.zeros(len(lon))
    for k in range(len(interp_ha)):
        H = interp_ha[k](points)
        fase = np.deg2rad(interp_hp[k](points))
        w = omega_rad[k]
        mask = ~np.isnan(H) & (H > 0)   # considera apenas amplitudes válidas
        eta[mask] += H[mask] * np.cos(w * horas - fase[mask])

    return eta

def identificar_colunas(df):
    """
    Identifica as colunas de latitude, longitude, profundidade e data/hora.
    Retorna os nomes originais.
    """
    # Remove espaços extras dos nomes
    df.columns = df.columns.str.strip()

    # Listas com nomes esperados (em minúsculas)
    lat_candidates = ['lat', 'latitude']
    lon_candidates = ['lon', 'long', 'longitude']
    z_candidates   = ['z', 'depth', 'profundidade', 'z1', 'Z1', 'depth_m']   # Adicionado 'z1'
    dt_candidates  = ['datetime', 'date', 'fecha', 'hora']

    col_lat = None
    col_lon = None
    col_z   = None
    col_dt  = None

    for col in df.columns:
        col_low = col.lower()
        if col_low in lat_candidates and col_lat is None:
            col_lat = col
        elif col_low in lon_candidates and col_lon is None:
            col_lon = col
        elif col_low in z_candidates and col_z is None:
            col_z = col
        elif col_low in dt_candidates and col_dt is None:
            col_dt = col

    # Se não encontrou datetime, tenta combinar fecha + hora
    if col_dt is None:
        fecha_col = next((c for c in df.columns if c.lower() == 'fecha'), None)
        hora_col  = next((c for c in df.columns if c.lower() == 'hora'), None)
        if fecha_col is not None and hora_col is not None:
            df['datetime'] = pd.to_datetime(df[fecha_col] + ' ' + df[hora_col].astype(str))
            col_dt = 'datetime'
        else:
            raise ValueError("Coluna de data/hora não encontrada")

    if col_lat is None or col_lon is None or col_z is None:
        raise ValueError("Faltam colunas de lat/lon/z")

    return col_lat, col_lon, col_z, col_dt

def renomear_seguro(df, mapping):
    """
    Renomeia colunas conforme mapping, evitando conflitos.
    Se o novo nome já existir, renomeia a coluna existente para 'nome_orig'.
    """
    for old, new in mapping.items():
        if old == new:
            continue
        if new in df.columns and new != old:
            df.rename(columns={new: f"{new}_orig"}, inplace=True)
        df.rename(columns={old: new}, inplace=True)
    return df

# =====================================================
# PROCESSAMENTO PRINCIPAL
# =====================================================

def processar():
    print("Carregando dados TPXO...")
    h_tpxo = xr.open_dataset(arquivo_h)

    # Preparar interpoladores
    lon_1d, lat_1d, interp_ha, interp_hp, omega_rad = preparar_interpoladores(h_tpxo)
    print(f"Grade TPXO: {len(lon_1d)} longitudes × {len(lat_1d)} latitudes")
    print(f"Intervalo de longitudes: {lon_1d.min():.2f}° a {lon_1d.max():.2f}°")
    print(f"Intervalo de latitudes:  {lat_1d.min():.2f}° a {lat_1d.max():.2f}°")

    arquivos = glob.glob(os.path.join(pasta_csv, "*.csv"))
    if not arquivos:
        print("Nenhum arquivo CSV encontrado.")
        return

    print(f"Encontrados {len(arquivos)} arquivos.\n")
    resumo = []

    for arq in arquivos:
        nome = os.path.basename(arq)
        print(f"Processando: {nome}")

        try:
            # Leitura do CSV
            try:
                df = pd.read_csv(arq, encoding='utf-8')
            except UnicodeDecodeError:
                df = pd.read_csv(arq, encoding='latin1')

            # Identificar colunas
            col_lat, col_lon, col_z, col_dt = identificar_colunas(df)

            # Renomear para nomes padrão
            mapping = {col_lat: 'lat', col_lon: 'lon', col_z: 'z', col_dt: 'datetime'}
            df = renomear_seguro(df, mapping)

            # Converter datetime
            df['datetime'] = pd.to_datetime(df['datetime'], errors='coerce')
            if df['datetime'].isna().any():
                data_hora = df['datetime'].dropna().iloc[0]
            else:
                data_hora = df['datetime'].iloc[0]

            # Horas desde época (1992-01-01)
            horas = horas_desde_epoca(data_hora)

            # Calcular maré para cada ponto
            eta = calcular_mare(df['lon'].values, df['lat'].values, horas,
                                lon_1d, lat_1d, interp_ha, interp_hp, omega_rad)

            # Delta espacial (IDW)
            delta = delta_idw(df['lon'].values, df['lat'].values)

            # Correção
            df['eta_MSL'] = eta
            df['Delta'] = delta
            df['Z_corrigido'] = df['z'] - (eta - delta)
            df['dif'] = df['Z_corrigido'] - df['z']

            # Salvar
            out_file = os.path.join(pasta_saida, nome.replace('.csv', '_corrigido.csv'))
            df.to_csv(out_file, index=False)

            # Resumo
            resumo.append({
                'Arquivo': nome,
                'Data_Hora': data_hora,
                'Eta_medio': np.nanmean(eta),
                'Delta_medio': np.nanmean(delta),
                'Correcao_media': np.nanmean(df['dif']),
                'Prof_orig_media': np.nanmean(df['z']),
                'Prof_corr_media': np.nanmean(df['Z_corrigido']),
                'Num_pontos': len(df)
            })

            print(f"  -> Correção média: {np.nanmean(df['dif']):+.3f} m")
            print(f"  -> η_MSL médio   : {np.nanmean(eta):+.3f} m")

        except Exception as e:
            print(f"  ERRO: {e}")
            if 'df' in locals():
                print("  Colunas:", list(df.columns))
            continue

    h_tpxo.close()

    if resumo:
        df_resumo = pd.DataFrame(resumo)
        df_resumo.to_csv(os.path.join(pasta_saida, 'resumo_correcoes.csv'), index=False)
        print("\nResumo salvo em:", os.path.join(pasta_saida, 'resumo_correcoes.csv'))
        return df_resumo
    else:
        print("Nenhum arquivo foi processado.")
        return None

# =====================================================
# EXECUÇÃO
# =====================================================
if __name__ == "__main__":
    df_resumo = processar()

