"""inicio do modelo"""

import os
import re
import pandas as pd
import numpy as np
from google.colab import drive

# ====================================================
# 1. CARGADOR DE DATOS - VERSION PARA DATOS CORREGIDOS
# ====================================================

class CargadorDatos:
    """Clase para carga y preprocesamiento de datos - ESPECIFICA PARA DATOS CON Z_corregido"""

    def __init__(self, config):
        self.config = config
        self.df_braza = None
        self.df_bat_anto = None
        self.df_bat_paranagua = None
        self.df_combined = None

    @staticmethod
    def remove_outliers_iqr(series, factor=1.5):
        """Limita outliers usando el metodo IQR (clip)"""
        Q1 = series.quantile(0.25)
        Q3 = series.quantile(0.75)
        IQR = Q3 - Q1
        lower_bound = Q1 - factor * IQR
        upper_bound = Q3 + factor * IQR
        return series.clip(lower_bound, upper_bound)

    def cargar_todos_datos(self):
        """Carga todos los conjuntos de datos segun configuracion"""
        print("=" * 80)
        print("CARGANDO DATOS DESDE GOOGLE DRIVE")
        print("=" * 80)

        # Montar Google Drive
        drive.mount('/content/drive', force_remount=True)

        # Cargar datos de Braza (calidad de agua)
        if self.config.get('load_braza', False):
            print("\n1. CARGANDO DATOS DE CALIDAD DE AGUA (BRAZA)")
            self.df_braza = self._cargar_braza()

        # Cargar datos de batimetria de Antonina
        if self.config.get('load_antonina', False):
            print("\n2. CARGANDO DATOS DE BATIMETRIA (ANTONINA)")
            self.df_bat_anto = self._cargar_batimetria_antonina(
                self.config['paths']['bat_anto'],
                self.config['patterns']['bat_anto'],
                'Antonina'
            )

        # Cargar datos de batimetria de Paranagua (archivos corregidos)
        if self.config.get('load_paranagua', False):
            print("\n3. CARGANDO DATOS DE BATIMETRIA (PARANAGUA) - ARCHIVOS CORREGIDOS")
            self.df_bat_paranagua = self._cargar_batimetria_paranagua(
                self.config['paths']['bat_paranagua'],
                'Paranagua'
            )

        # Verificar profundidades
        self.verificar_profundidades()

        # Combinar todos los datos de batimetria si es necesario
        if self.config.get('combine_datasets', False):
            print("\n4. COMBINANDO DATOS DE BATIMETRIA")
            self.df_combined = self._combinar_batimetria()

        print("\n" + "=" * 80)
        print("CARGA DE DATOS COMPLETADA")
        print("=" * 80)

        return {
            'braza': self.df_braza,
            'antonina': self.df_bat_anto,
            'paranagua': self.df_bat_paranagua,
            'combined': self.df_combined
        }

    def _cargar_braza(self):
        """Carga datos de Braza (calidad de agua)"""
        folder_path = self.config['paths']['braza']
        pattern = self.config['patterns']['braza']

        print(f"Directorio: {folder_path}")

        if not os.path.exists(folder_path):
            print(f" Error: Directorio no encontrado")
            return pd.DataFrame()

        archivos = [f for f in os.listdir(folder_path) if pattern.match(f)]

        if not archivos:
            print(" No se encontraron archivos")
            return pd.DataFrame()

        print(f" Encontrados {len(archivos)} archivos")
        dfs = []

        for filename in archivos:
            try:
                match = pattern.match(filename)
                fecha = pd.to_datetime(match.group(1), format='%Y%m%d')
                file_path = os.path.join(folder_path, filename)

                df = pd.read_csv(file_path)

                if df.empty:
                    print(f"    {filename} esta vacio")
                    continue

                # Verificar columnas requeridas
                columnas_requeridas = ['lon', 'lat', 'NDCI', 'NDTI', 'turbidity_NTU', 'chla_ugL']
                columnas_faltantes = [col for col in columnas_requeridas if col not in df.columns]

                if columnas_faltantes:
                    print(f"    {filename} falta: {columnas_faltantes}")
                    continue

                # Convertir tipos
                for col in columnas_requeridas:
                    df[col] = pd.to_numeric(df[col].astype(str).str.replace(',', '.'), errors='coerce')

                # Agregar informacion
                df['fecha'] = fecha
                df['ubicacion'] = 'Braza'
                df['tipo'] = 'calidad_agua'

                # Renombrar columnas para consistencia
                df = df.rename(columns={'long': 'X', 'lat': 'Y'})

                dfs.append(df)
                print(f"    {filename}: {len(df)} registros")

            except Exception as e:
                print(f"    Error en {filename}: {str(e)[:100]}")

        if dfs:
            df_final = pd.concat(dfs, ignore_index=True)
            print(f"\n Datos Braza cargados: {len(df_final)} registros")
            print(f"   Rango fechas: {df_final['fecha'].min().date()} a {df_final['fecha'].max().date()}")
            return df_final
        else:
            print(" No se pudieron cargar datos de Braza")
            return pd.DataFrame()

    def _cargar_batimetria_antonina(self, folder_path, pattern, nombre_ubicacion):
        """Carga datos de batimetria de Antonina (archivos sin corregir o ya corregidos)"""
        print(f"Directorio: {folder_path}")

        if not os.path.exists(folder_path):
            print(f" Error: Directorio no encontrado")
            return pd.DataFrame()

        todos_archivos = [f for f in os.listdir(folder_path) if f.endswith('.csv')]
        print(f" Archivos CSV encontrados: {len(todos_archivos)}")

        archivos_filtrados = [f for f in todos_archivos if pattern.match(f)]
        print(f" Archivos de Antonina encontrados: {len(archivos_filtrados)}")

        if not archivos_filtrados:
            print(f" ERROR: No se encontraron archivos para {nombre_ubicacion}")
            return pd.DataFrame()

        print(f" Archivos a procesar: {len(archivos_filtrados)}")
        dfs = []
        errores = []

        for i, filename in enumerate(archivos_filtrados):
            try:
                if i % 50 == 0 and i > 0:
                    print(f"\n  Procesando archivo {i+1}/{len(archivos_filtrados)}...")

                fecha_match = re.search(r'(\d{8})', filename)
                if fecha_match:
                    fecha = pd.to_datetime(fecha_match.group(1), format='%Y%m%d')
                else:
                    fecha = pd.Timestamp.now()

                file_path = os.path.join(folder_path, filename)
                df = pd.read_csv(file_path)

                if df.empty:
                    errores.append(f"{filename}: Vacio")
                    continue

                # Procesar coordenadas
                coordenadas_encontradas = False

                if 'X' in df.columns and 'Y' in df.columns:
                    coordenadas_encontradas = True
                elif 'lon' in df.columns and 'lat' in df.columns:
                    df['X'] = df['lon']
                    df['Y'] = df['lat']
                    coordenadas_encontradas = True
                elif 'long' in df.columns and 'lat' in df.columns:
                    df['X'] = df['long']
                    df['Y'] = df['lat']
                    coordenadas_encontradas = True

                if not coordenadas_encontradas:
                    errores.append(f"{filename}: Sin coordenadas")
                    continue

                # Procesar profundidad (buscar Z_corrigido o Z1 o z)
                if 'Z_corrigido' in df.columns:
                    df['Z1'] = pd.to_numeric(df['Z_corrigido'], errors='coerce')
                    df['profundidad_origen'] = 'Z_corrigido'
                elif 'Z_corregido' in df.columns:
                    df['Z1'] = pd.to_numeric(df['Z_corregido'], errors='coerce')
                    df['profundidad_origen'] = 'Z_corregido'
                elif 'Z1' in df.columns:
                    df['profundidad_origen'] = 'Z1'
                elif 'z' in df.columns:
                    df['Z1'] = pd.to_numeric(df['z'], errors='coerce')
                    df['profundidad_origen'] = 'z'
                else:
                    errores.append(f"{filename}: Sin columna de profundidad")
                    continue

                # Convertir coordenadas a numerico
                df['X'] = pd.to_numeric(df['X'], errors='coerce')
                df['Y'] = pd.to_numeric(df['Y'], errors='coerce')

                # Eliminar filas con NaN
                df = df.dropna(subset=['X', 'Y', 'Z1'])

                if df.empty:
                    errores.append(f"{filename}: No quedaron registros validos")
                    continue

                # Agregar metadatos
                df['fecha'] = fecha
                df['ubicacion'] = nombre_ubicacion
                df['nombre_archivo'] = filename
                df['tipo'] = 'batimetria'

                # Seleccionar columnas relevantes
                columnas_base = ['X', 'Y', 'Z1', 'fecha', 'ubicacion', 'nombre_archivo', 'tipo', 'profundidad_origen']

                # Agregar bandas espectrales si existen
                for banda in ['B2', 'B3', 'B4', 'B5', 'B8']:
                    if banda in df.columns:
                        df[banda] = pd.to_numeric(df[banda], errors='coerce')
                        columnas_base.append(banda)

                # Agregar indices si existen
                for indice in ['NDCI', 'NDTI', 'NDWI']:
                    if indice in df.columns:
                        df[indice] = pd.to_numeric(df[indice], errors='coerce')
                        columnas_base.append(indice)

                # Mantener solo columnas existentes
                columnas_finales = [col for col in columnas_base if col in df.columns]
                df = df[columnas_finales]

                dfs.append(df)

            except Exception as e:
                errores.append(f"{filename}: {str(e)[:100]}")
                continue

        if dfs:
            df_final = pd.concat(dfs, ignore_index=True)

            print(f"\n" + "="*60)
            print(f"RESUMEN CARGA {nombre_ubicacion.upper()}")
            print("="*60)
            print(f"Total archivos procesados: {len(archivos_filtrados)}")
            print(f"Archivos cargados exitosamente: {len(dfs)}")
            print(f"Total registros: {len(df_final)}")
            print(f"Fechas unicas: {df_final['fecha'].nunique()}")
            print(f"Rango profundidad: {df_final['Z1'].min():.2f} a {df_final['Z1'].max():.2f} m")
            print(f"Profundidad media: {df_final['Z1'].mean():.2f} +- {df_final['Z1'].std():.2f} m")
            print(f"Origen profundidad: {df_final['profundidad_origen'].value_counts().to_dict()}")

            if errores:
                print(f"\nErrores encontrados: {len(errores)}")
                for err in errores[:10]:
                    print(f"  - {err}")

            return df_final
        else:
            print(f"\n No se pudieron cargar datos de {nombre_ubicacion}")
            return pd.DataFrame()

    def _cargar_batimetria_paranagua(self, folder_path, nombre_ubicacion):
        """
        Carga datos de batimetria de Paranagua
        Formato esperado: Paranagua_1_yyyymmdd_corregido.csv
                          Paranagua_2_yyyymmdd_corregido.csv
                          Paranagua_3_yyyymmdd_corregido.csv
                          Paranagua_4_yyyymmdd_corregido.csv
        """
        print(f"Directorio: {folder_path}")

        if not os.path.exists(folder_path):
            print(f" Error: Directorio no encontrado")
            return pd.DataFrame()

        # Patron para archivos de Paranagua corregidos
        # Formato: Paranagua_1_20240101_corregido.csv
        patron_paranagua = re.compile(r'Paranagua_([1-4])_(\d{8})_corregido\.csv', re.IGNORECASE)

        todos_archivos = [f for f in os.listdir(folder_path) if f.endswith('.csv')]
        print(f" Archivos CSV encontrados: {len(todos_archivos)}")

        # Filtrar archivos que coinciden con el patron
        archivos_paranagua = []
        for f in todos_archivos:
            match = patron_paranagua.match(f)
            if match:
                archivos_paranagua.append((f, int(match.group(1)), match.group(2)))

        # Ordenar por numero (1,2,3,4)
        archivos_paranagua.sort(key=lambda x: x[1])

        if not archivos_paranagua:
            print(" ERROR: No se encontraron archivos con el formato esperado")
            print(" Formato esperado: Paranagua_1_yyyymmdd_corregido.csv")
            return pd.DataFrame()

        print(f" Archivos de Paranagua encontrados: {len(archivos_paranagua)}")
        for f, num, fecha_str in archivos_paranagua:
            print(f"    - Archivo {num}: {f} (fecha: {fecha_str})")

        dfs = []
        errores = []

        for filename, numero, fecha_str in archivos_paranagua:
            try:
                print(f"\n  Procesando archivo {numero}: {filename}")

                fecha = pd.to_datetime(fecha_str, format='%Y%m%d')
                file_path = os.path.join(folder_path, filename)
                df = pd.read_csv(file_path)

                if df.empty:
                    errores.append(f"{filename}: Vacio")
                    continue

                print(f"    Registros en archivo: {len(df)}")
                print(f"    Columnas disponibles: {list(df.columns)}")

                # Procesar coordenadas
                coordenadas_encontradas = False

                if 'X' in df.columns and 'Y' in df.columns:
                    coordenadas_encontradas = True
                elif 'lon' in df.columns and 'lat' in df.columns:
                    df['X'] = df['lon']
                    df['Y'] = df['lat']
                    coordenadas_encontradas = True
                elif 'long' in df.columns and 'lat' in df.columns:
                    df['X'] = df['long']
                    df['Y'] = df['lat']
                    coordenadas_encontradas = True

                if not coordenadas_encontradas:
                    errores.append(f"{filename}: Sin coordenadas")
                    continue

                # Procesar profundidad - BUSCAR Z_corrigido (ya corregido por marea)
                columna_profundidad = None
                for col_name in ['Z_corrigido', 'Z_corregido', 'Z_corrigida', 'Z_corregida']:
                    if col_name in df.columns:
                        columna_profundidad = col_name
                        break

                if columna_profundidad is None:
                    # Si no encuentra Z_corrigido, buscar z original
                    if 'z' in df.columns:
                        columna_profundidad = 'z'
                        print(f"    ADVERTENCIA: Usando '{columna_profundidad}' (original, no corregido)")
                    else:
                        errores.append(f"{filename}: No tiene Z_corrigido ni z")
                        continue

                df['Z1'] = pd.to_numeric(df[columna_profundidad], errors='coerce')
                df['profundidad_origen'] = columna_profundidad

                # Verificar valores validos
                if df['Z1'].count() == 0:
                    errores.append(f"{filename}: No hay valores validos en profundidad")
                    continue

                # Convertir coordenadas a numerico
                df['X'] = pd.to_numeric(df['X'].astype(str).str.replace(',', '.'), errors='coerce')
                df['Y'] = pd.to_numeric(df['Y'].astype(str).str.replace(',', '.'), errors='coerce')

                # Eliminar filas con NaN
                antes = len(df)
                df = df.dropna(subset=['X', 'Y', 'Z1'])
                despues = len(df)

                if despues == 0:
                    errores.append(f"{filename}: No quedaron registros validos despues de limpiar NaN")
                    continue

                if antes != despues:
                    print(f"    Eliminados {antes - despues} registros con NaN")

                # Agregar metadatos
                df['fecha'] = fecha
                df['ubicacion'] = f"{nombre_ubicacion}_{numero}"
                df['nombre_archivo'] = filename
                df['tipo'] = 'batimetria'
                df['numero_archivo'] = numero

                # Seleccionar columnas relevantes
                columnas_base = ['X', 'Y', 'Z1', 'fecha', 'ubicacion', 'nombre_archivo', 'tipo', 'profundidad_origen', 'numero_archivo']

                # Agregar bandas espectrales si existen
                for banda in ['B2', 'B3', 'B4', 'B5', 'B8']:
                    if banda in df.columns:
                        df[banda] = pd.to_numeric(df[banda], errors='coerce')
                        columnas_base.append(banda)

                # Agregar indices si existen
                for indice in ['NDCI', 'NDTI', 'NDWI']:
                    if indice in df.columns:
                        df[indice] = pd.to_numeric(df[indice], errors='coerce')
                        columnas_base.append(indice)

                # Mantener solo columnas existentes
                columnas_finales = [col for col in columnas_base if col in df.columns]
                df = df[columnas_finales]

                dfs.append(df)

                print(f"    OK: {len(df)} registros cargados exitosamente")
                print(f"    Rango profundidad: {df['Z1'].min():.2f} a {df['Z1'].max():.2f} m")
                print(f"    Profundidad media: {df['Z1'].mean():.2f} +- {df['Z1'].std():.2f} m")

            except Exception as e:
                errores.append(f"{filename}: {str(e)[:100]}")
                print(f"    ERROR: {str(e)[:100]}")
                continue

        if dfs:
            df_final = pd.concat(dfs, ignore_index=True)

            print(f"\n" + "="*60)
            print(f"RESUMEN CARGA {nombre_ubicacion.upper()}")
            print("="*60)
            print(f"Total archivos procesados: {len(archivos_paranagua)}")
            print(f"Archivos cargados exitosamente: {len(dfs)}")
            print(f"Total registros: {len(df_final)}")
            print(f"Distribucion por archivo:")
            for num in sorted(df_final['numero_archivo'].unique()):
                count = len(df_final[df_final['numero_archivo'] == num])
                print(f"  Archivo {num}: {count} registros")
            print(f"Fechas unicas: {df_final['fecha'].nunique()}")
            print(f"Rango profundidad: {df_final['Z1'].min():.2f} a {df_final['Z1'].max():.2f} m")
            print(f"Profundidad media: {df_final['Z1'].mean():.2f} +- {df_final['Z1'].std():.2f} m")
            print(f"Origen profundidad: {df_final['profundidad_origen'].value_counts().to_dict()}")

            if errores:
                print(f"\nErrores encontrados: {len(errores)}")
                for err in errores[:10]:
                    print(f"  - {err}")

            return df_final
        else:
            print(f"\n No se pudieron cargar datos de {nombre_ubicacion}")
            return pd.DataFrame()

    def _combinar_batimetria(self):
        """Combina todos los datos de batimetria"""
        dfs_a_combinar = []

        if self.df_bat_anto is not None and not self.df_bat_anto.empty:
            dfs_a_combinar.append(self.df_bat_anto)

        if self.df_bat_paranagua is not None and not self.df_bat_paranagua.empty:
            dfs_a_combinar.append(self.df_bat_paranagua)

        if not dfs_a_combinar:
            print(" No hay datos de batimetria para combinar")
            return pd.DataFrame()

        df_combined = pd.concat(dfs_a_combinar, ignore_index=True)

        print(f"\n Datos combinados: {len(df_combined)} registros")
        print(f"  Distribucion por ubicacion:")
        print(df_combined['ubicacion'].value_counts())

        return df_combined

    def verificar_profundidades(self):
        """Verifica que se este usando la columna correcta de profundidad"""
        print("\n" + "="*80)
        print("VERIFICACION DE COLUMNAS DE PROFUNDIDAD")
