import os
import re
import pandas as pd
import numpy as np
from google.colab import drive

class CargadorDatos:
    """Clase para carga y preprocesamiento de datos - CORREGIDA"""

    def __init__(self, config):
        self.config = config
        self.df_braza = None
        self.df_bat_anto = None
        self.df_bat_paranagua = None
        self.df_combined = None

    @staticmethod
    def remove_outliers_iqr(series, factor=1.5):
        """Limita outliers usando el método IQR (clip, no eliminación)"""
        Q1 = series.quantile(0.25)
        Q3 = series.quantile(0.75)
        IQR = Q3 - Q1
        lower_bound = Q1 - factor * IQR
        upper_bound = Q3 + factor * IQR
        return series.clip(lower_bound, upper_bound)

    def _estandarizar_columnas(self, df):
        """Estandariza nombres de columnas a un formato común"""
        df = df.copy()
        mapeo = {
            # Coordenadas
            'Long': 'X', 'long': 'X', 'LONG': 'X', 'Lon': 'X', 'lon': 'X',
            'Lat': 'Y', 'lat': 'Y', 'LAT': 'Y',
            # Bandas
            'b2': 'B2', 'b3': 'B3', 'b4': 'B4', 'b5': 'B5', 'b8': 'B8',
            # Índices
            'ndci': 'NDCI', 'ndti': 'NDTI', 'ndwi': 'NDWI'
        }
        for orig, dest in mapeo.items():
            if orig in df.columns and dest not in df.columns:
                df.rename(columns={orig: dest}, inplace=True)
        return df

    def verificar_profundidad_paranagua(self):
        """Verifica específicamente que Paranaguá está usando Z_corrigido"""
        if self.df_bat_paranagua is None or self.df_bat_paranagua.empty:
            print("\n No hay datos de Paranaguá para verificar")
            return

        print("\n" + "="*80)
        print("VERIFICACIÓN ESPECÍFICA: PARANAGUÁ - Z_corrigido")
        print("="*80)

        if 'profundidad_origen' in self.df_bat_paranagua.columns:
            origen = self.df_bat_paranagua['profundidad_origen'].iloc[0]
            print(f"\n Columna de profundidad utilizada: {origen}")
            if 'Z_corrigido' in origen or 'Z_corregido' in origen:
                print("    CORRECTO: Se está usando Z_corrigido (corregido por marea)")
            else:
                print(f"    ADVERTENCIA: Se está usando {origen} en lugar de Z_corrigido")
        else:
            print("    No se encontró información de columna de origen")

        print(f"\n Estadísticas de profundidad (Paranaguá):")
        print(f"   • Mínimo: {self.df_bat_paranagua['Z1'].min():.2f} m")
        print(f"   • Máximo: {self.df_bat_paranagua['Z1'].max():.2f} m")
        print(f"   • Media:  {self.df_bat_paranagua['Z1'].mean():.2f} m")
        print(f"   • Mediana: {self.df_bat_paranagua['Z1'].median():.2f} m")
        print(f"   • Desv. Std: {self.df_bat_paranagua['Z1'].std():.2f} m")

        negativos = (self.df_bat_paranagua['Z1'] < 0).sum()
        positivos = (self.df_bat_paranagua['Z1'] > 0).sum()
        print(f"\n   • Valores negativos (agua): {negativos} ({negativos/len(self.df_bat_paranagua)*100:.1f}%)")
        print(f"   • Valores positivos (tierra): {positivos} ({positivos/len(self.df_bat_paranagua)*100:.1f}%)")

        if 'Z_original' in self.df_bat_paranagua.columns:
            print(f"\n Comparación Z_corrigido vs Z_original:")
            print(f"   • Z_corrigido (media): {self.df_bat_paranagua['Z1'].mean():.2f} m")
            print(f"   • Z_original (media): {self.df_bat_paranagua['Z_original'].mean():.2f} m")
            print(f"   • Diferencia media (efecto marea): {self.df_bat_paranagua['Z1'].mean() - self.df_bat_paranagua['Z_original'].mean():.2f} m")

    def limpiar_profundidad(self, df, depth_col='Z1', min_depth=-50, max_depth=0):
        """
        LIMPIEZA ESPECÍFICA PARA PROFUNDIDAD (NUEVO MÉTODO)
        - Elimina valores positivos (tierra)
        - Elimina valores extremadamente negativos (errores)
        - Mantiene la jerarquía: -20 es más profundo que -5
        """
        if df is None or df.empty or depth_col not in df.columns:
            return df

        df_clean = df.copy()
        original_len = len(df_clean)

        print("\n" + "="*60)
        print(" LIMPIEZA ESPECÍFICA DE PROFUNDIDAD")
        print("="*60)

        # Estadísticas antes
        print("\n ANTES DE LA LIMPIEZA:")
        print(f"  • Registros totales: {original_len}")
        print(f"  • Rango: [{df_clean[depth_col].min():.2f}, {df_clean[depth_col].max():.2f}] m")
        print(f"  • Media: {df_clean[depth_col].mean():.2f} ± {df_clean[depth_col].std():.2f} m")

        # 1. ELIMINAR valores positivos (tierra)
        n_positivos = (df_clean[depth_col] > 0).sum()
        if n_positivos > 0:
            df_clean = df_clean[df_clean[depth_col] <= 0].copy()
            print(f"\n ELIMINADOS {n_positivos} registros con profundidad POSITIVA (tierra)")

        # 2. ELIMINAR valores muy profundos (errores)
        n_muy_profundo = (df_clean[depth_col] < min_depth).sum()
        if n_muy_profundo > 0:
            df_clean = df_clean[df_clean[depth_col] >= min_depth].copy()
            print(f" ELIMINADOS {n_muy_profundo} registros con profundidad < {min_depth}m (errores)")

        # 3. Estadísticas después
        eliminados = original_len - len(df_clean)
        print("\n DESPUÉS DE LA LIMPIEZA:")
        print(f"  • Registros restantes: {len(df_clean)}")
        print(f"  • Eliminados: {eliminados} ({eliminados/original_len*100:.1f}%)")
        print(f"  • Rango: [{df_clean[depth_col].min():.2f}, {df_clean[depth_col].max():.2f}] m")
        print(f"  • Media: {df_clean[depth_col].mean():.2f} ± {df_clean[depth_col].std():.2f} m")

        # Verificar jerarquía de profundidad
        print(f"\n JERARQUÍA DE PROFUNDIDAD:")
        print(f"  • Más profundo: {df_clean[depth_col].min():.2f} m")
        print(f"  • Más superficial: {df_clean[depth_col].max():.2f} m")

        if df_clean[depth_col].min() < df_clean[depth_col].max():
            print(f"   OK: {df_clean[depth_col].min():.2f} es más profundo que {df_clean[depth_col].max():.2f}")

        return df_clean

    def cargar_todos_datos(self):
        """Carga todos los conjuntos de datos según configuración"""
        print("=" * 80)
        print("CARGANDO DATOS DESDE GOOGLE DRIVE")
        print("=" * 80)

        drive.mount('/content/drive', force_remount=True)

        if self.config['load_braza']:
            print("\n1. CARGANDO DATOS DE CALIDAD DE AGUA (BRAZA)")
            self.df_braza = self._cargar_braza()

        if self.config['load_antonina']:
            print("\n2. CARGANDO DATOS DE BATIMETRÍA (ANTONINA)")
            self.df_bat_anto = self._cargar_batimetria(
                self.config['paths']['bat_anto'],
                self.config['patterns']['bat_anto'],
                'Antonina',
                es_paranagua=False
            )

        if self.config['load_paranagua']:
            print("\n3. CARGANDO DATOS DE BATIMETRÍA (PARANAGUÁ)")
            self.df_bat_paranagua = self._cargar_batimetria(
                self.config['paths']['bat_paranagua'],
                self.config['patterns']['bat_paranagua'],
                'Paranaguá',
                es_paranagua=True
            )

        self.verificar_profundidades()

        if self.config['combine_datasets']:
            print("\n4. COMBINANDO DATOS DE BATIMETRÍA")
            self.df_combined = self._combinar_batimetria()

        print("\n" + "=" * 80)
        print("CARGA DE DATOS COMPLETADA")
        print("=" * 80)

        return {
            'braza': self.df_braza,
            'antonina': self.df_bat_anto,
            'paranagua': self.df_bat_paranagua,
            'combined': self.df_combined
        }

    def _cargar_braza(self):
        """Carga datos de Braza (calidad de agua)"""
        folder_path = self.config['paths']['braza']
        pattern = self.config['patterns']['braza']

        print(f"Directorio: {folder_path}")

        if not os.path.exists(folder_path):
            print(f" Error: Directorio no encontrado")
            return pd.DataFrame()

        archivos = [f for f in os.listdir(folder_path) if pattern.match(f)]

        if not archivos:
            print(" No se encontraron archivos")
            return pd.DataFrame()

        print(f" Encontrados {len(archivos)} archivos")
        dfs = []

        for filename in archivos:
            try:
                match = pattern.match(filename)
                fecha = pd.to_datetime(match.group(1), format='%Y%m%d')
                file_path = os.path.join(folder_path, filename)

                df = pd.read_csv(file_path)

                if df.empty:
                    print(f"    {filename} está vacío")
                    continue

                columnas_requeridas = ['lon', 'lat', 'NDCI', 'NDTI', 'turbidity_NTU', 'chla_ugL']
                columnas_faltantes = [col for col in columnas_requeridas if col not in df.columns]

                if columnas_faltantes:
                    print(f"    {filename} falta: {columnas_faltantes}")
                    continue

                for col in columnas_requeridas:
                    df[col] = pd.to_numeric(df[col].astype(str).str.replace(',', '.'), errors='coerce')

                df['fecha'] = fecha
                df['ubicacion'] = 'Braza'
                df['tipo'] = 'calidad_agua'
                df = df.rename(columns={'lon': 'X', 'lat': 'Y'})

                dfs.append(df)
                print(f"    {filename}: {len(df)} registros")

            except Exception as e:
                print(f"    Error en {filename}: {str(e)[:100]}")

        if dfs:
            df_final = pd.concat(dfs, ignore_index=True)
            print(f"\n Datos Braza cargados: {len(df_final)} registros")
            print(f"   Rango fechas: {df_final['fecha'].min().date()} a {df_final['fecha'].max().date()}")
            print(f"   Columnas: {list(df_final.columns)}")
            return df_final
        else:
            print(" No se pudieron cargar datos de Braza")
            return pd.DataFrame()

    def _cargar_batimetria(self, folder_path, pattern, nombre_ubicacion, es_paranagua=False):
        """Carga datos de batimetría - VERSIÓN CORREGIDA"""
        print(f"Directorio: {folder_path}")

        if not os.path.exists(folder_path):
            print(f" Error: Directorio no encontrado")
            return pd.DataFrame()

        todos_archivos = [f for f in os.listdir(folder_path) if f.endswith('.csv')]
        print(f" Archivos CSV encontrados: {len(todos_archivos)}")

        #  CORRECCIÓN PRINCIPAL: Filtrar específicamente archivos de Paranaguá
        if es_paranagua:
            # Buscar archivos que contengan 'Paranagua' en el nombre
            archivos_filtrados = [f for f in todos_archivos if 'Paranagua' in f]
            print(f" Archivos de Paranaguá encontrados: {len(archivos_filtrados)}")

            # Si no encuentra, intentar con patrón
            if not archivos_filtrados:
                archivos_filtrados = [f for f in todos_archivos if pattern.match(f)]
                print(f" Usando patrón alternativo: {len(archivos_filtrados)} archivos")
        else:
            archivos_filtrados = [f for f in todos_archivos if pattern.match(f)]
            print(f" Archivos de Antonina encontrados: {len(archivos_filtrados)}")

        if not archivos_filtrados:
            print(f" ERROR: No se encontraron archivos para {nombre_ubicacion}")
            return pd.DataFrame()

        print(f" Archivos a procesar: {len(archivos_filtrados)}")
        dfs = []
        errores = []

        for i, filename in enumerate(archivos_filtrados):
            try:
                if i % 50 == 0 and i > 0:
                    print(f"\n  Procesando archivo {i+1}/{len(archivos_filtrados)}...")

                fecha_match = re.search(r'(\d{8})', filename)
                fecha = pd.to_datetime(fecha_match.group(1), format='%Y%m%d') if fecha_match else pd.Timestamp.now()

                file_path = os.path.join(folder_path, filename)
                df = pd.read_csv(file_path)

                if df.empty:
                    errores.append(f"{filename}: Vacío")
                    continue

                df = self._estandarizar_columnas(df)

                # Detección de profundidad
                profundidad_col = None
                if 'Z_corrigido' in df.columns:
                    profundidad_col = 'Z_corrigido'
                elif 'Z_corregido' in df.columns:
                    profundidad_col = 'Z_corregido'
                elif 'Z_corrigida' in df.columns:
                    profundidad_col = 'Z_corrigida'
                elif 'Z_corregida' in df.columns:
                    profundidad_col = 'Z_corregida'
                elif 'Z' in df.columns:
                    profundidad_col = 'Z'
                elif 'Z1' in df.columns:
                    profundidad_col = 'Z1'

                if profundidad_col is None:
                    errores.append(f"{filename}: No tiene columna de profundidad")
                    continue

                df['Z_original'] = df[profundidad_col]
                df['Z1'] = pd.to_numeric(df[profundidad_col], errors='coerce')
                df['profundidad_origen'] = profundidad_col

                if 'X' not in df.columns or 'Y' not in df.columns:
                    errores.append(f"{filename}: Sin coordenadas después de estandarizar")
                    continue

                df['X'] = pd.to_numeric(df['X'], errors='coerce')
                df['Y'] = pd.to_numeric(df['Y'], errors='coerce')
                df = df.dropna(subset=['X', 'Y', 'Z1'])

                if df.empty:
                    errores.append(f"{filename}: No quedaron registros válidos después de limpiar NaN")
                    continue

                if es_paranagua and i == 0:
                    print(f"\n    PRIMER ARCHIVO - VERIFICACIÓN:")
                    print(f"     • Columna usada para profundidad: {profundidad_col}")
                    print(f"     • Rango de Z1: {df['Z1'].min():.2f} a {df['Z1'].max():.2f} m")
                    print(f"     • Media Z1: {df['Z1'].mean():.2f} m")
                    print(f"     • Rango X: {df['X'].min():.2f} a {df['X'].max():.2f}")
                    print(f"     • Rango Y: {df['Y'].min():.2f} a {df['Y'].max():.2f}")

                df['fecha'] = fecha
                df['ubicacion'] = nombre_ubicacion
                df['nombre_archivo'] = filename
                df['tipo'] = 'batimetria'

                columnas_base = ['X', 'Y', 'Z1', 'Z_original', 'fecha', 'ubicacion', 'nombre_archivo', 'tipo', 'profundidad_origen']
                bandas = ['B2', 'B3', 'B4', 'B5', 'B8']
                indices = ['NDCI', 'NDTI', 'NDWI']

                for col in bandas + indices:
                    if col in df.columns:
                        df[col] = pd.to_numeric(df[col], errors='coerce')
                        columnas_base.append(col)

                columnas_finales = [col for col in columnas_base if col in df.columns]
                df = df[columnas_finales]

                dfs.append(df)

                if (i+1) % 100 == 0:
                    print(f"     Procesados {i+1} archivos, {len(dfs)} cargados exitosamente")

            except Exception as e:
                errores.append(f"{filename}: {str(e)[:100]}")
                continue

        if dfs:
            df_final = pd.concat(dfs, ignore_index=True)

            print(f"\n" + "="*60)
            print(f" RESUMEN CARGA {nombre_ubicacion.upper()}")
            print("="*60)
            print(f"Total archivos procesados: {len(archivos_filtrados)}")
            print(f"Archivos cargados exitosamente: {len(dfs)}")
            print(f"Total registros: {len(df_final)}")
            print(f"Fechas únicas: {df_final['fecha'].nunique()}")
            print(f" Rango profundidad (Z1): {df_final['Z1'].min():.2f} a {df_final['Z1'].max():.2f} m")
            print(f" Profundidad media: {df_final['Z1'].mean():.2f} ± {df_final['Z1'].std():.2f} m")
            print(f" Origen profundidad: {df_final['profundidad_origen'].value_counts().to_dict()}")
            print(f" Rango X: {df_final['X'].min():.2f} a {df_final['X'].max():.2f}")
            print(f" Rango Y: {df_final['Y'].min():.2f} a {df_final['Y'].max():.2f}")

            if errores:
                print(f"\n Errores encontrados: {len(errores)}")
                if len(errores) <= 10:
                    for err in errores:
                        print(f"  - {err}")
                else:
                    print(f"  Mostrando primeros 10 errores:")
                    for err in errores[:10]:
                        print(f"  - {err}")

            return df_final
        else:
            print(f"\n No se pudieron cargar datos de {nombre_ubicacion}")
            if errores:
                print(f"Errores ({len(errores)}):")
                for err in errores[:20]:
                    print(f"  - {err}")
            return pd.DataFrame()

    def _combinar_batimetria(self):
        """Combina todos los datos de batimetría"""
        dfs_a_combinar = []
        if self.df_bat_anto is not None and not self.df_bat_anto.empty:
            dfs_a_combinar.append(self.df_bat_anto)
        if self.df_bat_paranagua is not None and not self.df_bat_paranagua.empty:
            dfs_a_combinar.append(self.df_bat_paranagua)
        if not dfs_a_combinar:
            print(" No hay datos de batimetría para combinar")
            return pd.DataFrame()
        df_combined = pd.concat(dfs_a_combinar, ignore_index=True)
        print(f"\n Datos combinados: {len(df_combined)} registros")
        print(f"   Distribución por ubicación:")
        print(df_combined['ubicacion'].value_counts())
        return df_combined

