# ====================================================
# NUEVO BLOQUE: ANÁLISIS DE CASOS CON DIFERENTES CORRECCIONES DE AGUA
# ====================================================

class AnalisisCasosCorreccionAgua:
    """
    Clase para ejecutar el análisis con diferentes configuraciones de corrección de agua
    Casos:
    1. Sin considerar corrección de agua
    2. Considerando solo GMM para NDCI
    3. Considerando solo GMM para NDTI
    4. Considerando GMM para NDCI y NDTI juntos
    """

    def __init__(self, config_base):
        self.config_base = config_base.copy()
        self.resultados_casos = {}

    def _modificar_config_para_caso(self, caso):
        """
        Modifica la configuración según el caso de corrección de agua
        """
        config = self.config_base.copy()

        if caso == 1:
            # Caso 1: Sin considerar corrección de agua
            config['use_clear_water_only'] = False
            config['clear_water_method'] = None
            print("\n" + "="*80)
            print("CASO 1: SIN CORRECCIÓN DE AGUA")
            print("="*80)
            print("  • No se aplica clasificación de agua clara")
            print("  • Se usan todos los datos disponibles")

        elif caso == 2:
            # Caso 2: Solo GMM para NDCI
            config['use_clear_water_only'] = True
            config['clear_water_method'] = 'gmm_ndci_only'
            print("\n" + "="*80)
            print("CASO 2: CORRECCIÓN CON GMM PARA NDCI")
            print("="*80)
            print("  • Clasificación de agua clara usando solo NDCI")
            print("  • GMM entrenado con NDCI")

        elif caso == 3:
            # Caso 3: Solo GMM para NDTI
            config['use_clear_water_only'] = True
            config['clear_water_method'] = 'gmm_ndti_only'
            print("\n" + "="*80)
            print("CASO 3: CORRECCIÓN CON GMM PARA NDTI")
            print("="*80)
            print("  • Clasificación de agua clara usando solo NDTI")
            print("  • GMM entrenado con NDTI")

        elif caso == 4:
            # Caso 4: GMM para NDCI y NDTI juntos
            config['use_clear_water_only'] = True
            config['clear_water_method'] = 'gmm_combined'
            print("\n" + "="*80)
            print("CASO 4: CORRECCIÓN CON GMM PARA NDCI + NDTI")
            print("="*80)
            print("  • Clasificación de agua clara usando NDCI y NDTI")
            print("  • GMM entrenado con ambas variables")

        return config

    def _modificar_preprocessor_para_caso(self, preprocessor, caso):
        """
        Modifica el preprocesador según el caso
        """
        if caso == 1:
            # Sobrescribir método de clasificación para que no clasifique
            def _classify_no_filter(self, df_satelital, df_braza=None):
                print("  → Sin filtro de agua clara - usando todos los datos")
                df_satelital['is_clear_water'] = True
                return df_satelital

            preprocessor._classify_clear_water_calibrated = _classify_no_filter.__get__(preprocessor)
            preprocessor._classify_clear_water_basic = _classify_no_filter.__get__(preprocessor)

        elif caso == 2:
            # GMM solo con NDCI
            def _classify_gmm_ndci(self, df_satelital, df_braza=None):
                print("  → Clasificando agua clara con GMM (solo NDCI)...")

                # Preparar datos para GMM
                X_gmm = df_satelital[['NDCI']].dropna().values

                if len(X_gmm) < 100:
                    print(f"    Insuficientes datos: {len(X_gmm)} muestras")
                    df_satelital['is_clear_water'] = True
                    return df_satelital

                # Submuestreo si es necesario
                if len(X_gmm) > 10000:
                    indices = np.random.choice(len(X_gmm), 10000, replace=False)
                    X_gmm_sample = X_gmm[indices]
                else:
                    X_gmm_sample = X_gmm

                # Entrenar GMM
                from sklearn.mixture import GaussianMixture
                gmm = GaussianMixture(n_components=2, random_state=42)
                gmm.fit(X_gmm_sample)

                # Predecir
                labels = gmm.predict(X_gmm)
                df_satelital['gmm_label'] = np.nan
                valid_indices = df_satelital[['NDCI']].dropna().index
                df_satelital.loc[valid_indices, 'gmm_label'] = labels

                # Identificar componente de agua clara (menor NDCI)
                df_temp = df_satelital.dropna(subset=['gmm_label'])
                comp_stats = []
                for comp in np.unique(labels):
                    mask = df_temp['gmm_label'] == comp
                    comp_stats.append({
                        'component': comp,
                        'mean_NDCI': df_temp.loc[mask, 'NDCI'].mean(),
                        'n_samples': mask.sum()
                    })

                comp_stats = pd.DataFrame(comp_stats).sort_values('mean_NDCI')
                clear_comp = int(comp_stats.iloc[0]['component'])

                df_satelital['is_clear_water'] = (df_satelital['gmm_label'] == clear_comp)

                print(f"    Componente agua clara: {clear_comp}")
                print(f"    Porcentaje agua clara: {df_satelital['is_clear_water'].mean()*100:.1f}%")

                return df_satelital

            preprocessor._classify_clear_water_calibrated = _classify_gmm_ndci.__get__(preprocessor)
            preprocessor._classify_clear_water_basic = _classify_gmm_ndci.__get__(preprocessor)

        elif caso == 3:
            # GMM solo con NDTI
            def _classify_gmm_ndti(self, df_satelital, df_braza=None):
                print("  → Clasificando agua clara con GMM (solo NDTI)...")

                # Preparar datos para GMM
                X_gmm = df_satelital[['NDTI']].dropna().values

                if len(X_gmm) < 100:
                    print(f"    Insuficientes datos: {len(X_gmm)} muestras")
                    df_satelital['is_clear_water'] = True
                    return df_satelital

                if len(X_gmm) > 10000:
                    indices = np.random.choice(len(X_gmm), 10000, replace=False)
                    X_gmm_sample = X_gmm[indices]
                else:
                    X_gmm_sample = X_gmm

                from sklearn.mixture import GaussianMixture
                gmm = GaussianMixture(n_components=2, random_state=42)
                gmm.fit(X_gmm_sample)

                labels = gmm.predict(X_gmm)
                df_satelital['gmm_label'] = np.nan
                valid_indices = df_satelital[['NDTI']].dropna().index
                df_satelital.loc[valid_indices, 'gmm_label'] = labels

                # Identificar componente de agua clara (menor NDTI)
                df_temp = df_satelital.dropna(subset=['gmm_label'])
                comp_stats = []
                for comp in np.unique(labels):
                    mask = df_temp['gmm_label'] == comp
                    comp_stats.append({
                        'component': comp,
                        'mean_NDTI': df_temp.loc[mask, 'NDTI'].mean(),
                        'n_samples': mask.sum()
                    })

                comp_stats = pd.DataFrame(comp_stats).sort_values('mean_NDTI')
                clear_comp = int(comp_stats.iloc[0]['component'])

                df_satelital['is_clear_water'] = (df_satelital['gmm_label'] == clear_comp)

                print(f"    Componente agua clara: {clear_comp}")
                print(f"    Porcentaje agua clara: {df_satelital['is_clear_water'].mean()*100:.1f}%")

                return df_satelital

            preprocessor._classify_clear_water_calibrated = _classify_gmm_ndti.__get__(preprocessor)
            preprocessor._classify_clear_water_basic = _classify_gmm_ndti.__get__(preprocessor)

        elif caso == 4:
            # GMM con NDCI + NDTI (método original)
            def _classify_gmm_combined(self, df_satelital, df_braza=None):
                print("  → Clasificando agua clara con GMM (NDCI + NDTI)...")

                X_gmm = df_satelital[['NDCI', 'NDTI']].dropna().values

                if len(X_gmm) < 100:
                    print(f"    Insuficientes datos: {len(X_gmm)} muestras")
                    df_satelital['is_clear_water'] = True
                    return df_satelital

                if len(X_gmm) > 10000:
                    indices = np.random.choice(len(X_gmm), 10000, replace=False)
                    X_gmm_sample = X_gmm[indices]
                else:
                    X_gmm_sample = X_gmm

                from sklearn.mixture import GaussianMixture
                gmm = GaussianMixture(n_components=2, random_state=42)
                gmm.fit(X_gmm_sample)

                labels = gmm.predict(X_gmm)
                df_satelital['gmm_label'] = np.nan
                valid_indices = df_satelital[['NDCI', 'NDTI']].dropna().index
                df_satelital.loc[valid_indices, 'gmm_label'] = labels

                df_temp = df_satelital.dropna(subset=['gmm_label'])
                comp_stats = []
                for comp in np.unique(labels):
                    mask = df_temp['gmm_label'] == comp
                    comp_stats.append({
                        'component': comp,
                        'mean_NDTI': df_temp.loc[mask, 'NDTI'].mean(),
                        'mean_NDCI': df_temp.loc[mask, 'NDCI'].mean(),
                        'n_samples': mask.sum()
                    })

                comp_stats = pd.DataFrame(comp_stats).sort_values('mean_NDTI')
                clear_comp = int(comp_stats.iloc[0]['component'])

                df_satelital['is_clear_water'] = (df_satelital['gmm_label'] == clear_comp)

                print(f"    Componente agua clara: {clear_comp}")
                print(f"    Porcentaje agua clara: {df_satelital['is_clear_water'].mean()*100:.1f}%")

                return df_satelital

            preprocessor._classify_clear_water_calibrated = _classify_gmm_combined.__get__(preprocessor)
            preprocessor._classify_clear_water_basic = _classify_gmm_combined.__get__(preprocessor)

        return preprocessor

    def ejecutar_casos(self):
        """
        Ejecuta los 4 casos de corrección de agua y compila resultados
        """
        print("\n" + "="*100)
        print(" " * 30 + "ANÁLISIS DE CASOS DE CORRECCIÓN DE AGUA")
        print("="*100)

        # Casos a ejecutar
        casos = [1, 2, 3, 4]

        for caso in casos:
            print(f"\n{'='*100}")
            print(f" EJECUTANDO CASO {caso} ".center(100, "="))
            print(f"{'='*100}")

            # Modificar configuración según caso
            config_caso = self._modificar_config_para_caso(caso)

            # Ejecutar pipeline con la configuración modificada
            pipeline = SDBPipeline(config_caso)

            # Sobrescribir el método de clasificación según el caso
            pipeline.preprocessor = DataPreprocessor(config_caso)
            pipeline.preprocessor = self._modificar_preprocessor_para_caso(pipeline.preprocessor, caso)

            # Ejecutar pipeline
            try:
                resultados = pipeline.run()

                # Extraer resultados de métricas
                if 'results' in resultados and resultados['results'] is not None:
                    df_results = resultados['results']
                    df_comparison = resultados.get('df_comparison', None)

                    # Almacenar resultados
                    self.resultados_casos[f'caso_{caso}'] = {
                        'config': config_caso,
                        'results_df': df_results,
                        'df_comparison': df_comparison,
                        'pipeline': pipeline
                    }

                    print(f"\n--- RESULTADOS CASO {caso} ---")
                    print(df_results.round(4))

            except Exception as e:
                print(f"\n Error en caso {caso}: {e}")
                import traceback
                traceback.print_exc()
                self.resultados_casos[f'caso_{caso}'] = {'error': str(e)}

        return self.resultados_casos

    def mostrar_comparacion_casos(self):
        """
        Muestra una tabla comparativa de los resultados de los diferentes casos
        """
        print("\n" + "="*100)
        print(" " * 35 + "COMPARACIÓN DE CASOS DE CORRECCIÓN DE AGUA")
        print("="*100)

        # Recopilar métricas por caso y modelo
        metricas_por_caso = {}
        modelos = ['Lyzenga', 'Stumpf', 'RF', 'GB', 'XGB']
        metricas_interes = ['RMSE', 'MAE', 'R2']

        for caso_name, caso_data in self.resultados_casos.items():
            if 'error' in caso_data:
                continue

            df_results = caso_data.get('results_df')
            if df_results is None or df_results.empty:
                continue

            caso_metricas = {}
            for modelo in modelos:
                if modelo in df_results.index:
                    caso_metricas[modelo] = {}
                    for metrica in metricas_interes:
                        if metrica in df_results.columns:
                            valor = df_results.loc[modelo, metrica]
                            caso_metricas[modelo][metrica] = valor

            metricas_por_caso[caso_name] = caso_metricas

        if not metricas_por_caso:
            print("No hay resultados para comparar")
            return

        # Crear tabla comparativa
        print("\n" + "="*120)
        print("TABLA COMPARATIVA DE MÉTRICAS POR CASO")
        print("="*120)

        # Encabezado
        header = f"{'Modelo':<12}"
        for caso in metricas_por_caso.keys():
            header += f" | {caso.upper():^35}"
        print(header)
        print("-" * (12 + 37 * len(metricas_por_caso)))

        # Para cada modelo
        for modelo in modelos:
            row = f"{modelo:<12}"
            all_nan = True

            for caso_name, caso_metricas in metricas_por_caso.items():
                if modelo in caso_metricas:
                    all_nan = False
                    m = caso_metricas[modelo]
                    rmse = m.get('RMSE', np.nan)
                    mae = m.get('MAE', np.nan)
                    r2 = m.get('R2', np.nan)

                    if not np.isnan(rmse):
                        row += f" | RMSE:{rmse:.3f} MAE:{mae:.3f} R²:{r2:.3f}"
                    else:
                        row += f" | {'--/--/--':^35}"
                else:
                    row += f" | {'---':^35}"

            if not all_nan:
                print(row)

        print("\n" + "="*120)
        print("LEGENDAS:")
        print("  • RMSE: Raíz del Error Cuadrático Medio (menor es mejor)")
        print("  • MAE: Error Absoluto Medio (menor es mejor)")
        print("  • R²: Coeficiente de Determinación (mayor es mejor, máximo 1.0)")
        print("\n  • CASO 1: Sin corrección de agua")
        print("  • CASO 2: GMM solo con NDCI")
        print("  • CASO 3: GMM solo con NDTI")
        print("  • CASO 4: GMM con NDCI + NDTI")
        print("="*120)

        # Gráfico comparativo
        self._plot_comparacion_casos(metricas_por_caso, modelos, metricas_interes)

        # Recomendación
        self._recomendar_mejor_caso(metricas_por_caso, modelos)

    def _plot_comparacion_casos(self, metricas_por_caso, modelos, metricas_interes):
        """
        Crea gráficos comparativos entre casos
        """
        try:
            # Preparar datos para gráficos
            casos = list(metricas_por_caso.keys())
            n_casos = len(casos)
            n_metricas = len(metricas_interes)

            fig, axes = plt.subplots(1, n_metricas, figsize=(6*n_metricas, 5))
            if n_metricas == 1:
                axes = [axes]

            for idx, metrica in enumerate(metricas_interes):
                ax = axes[idx]

                # Recopilar valores por modelo y caso
                data = {}
                for modelo in modelos:
                    data[modelo] = []
                    for caso in casos:
                        caso_metricas = metricas_por_caso.get(caso, {})
                        if modelo in caso_metricas and metrica in caso_metricas[modelo]:
                            valor = caso_metricas[modelo][metrica]
                            data[modelo].append(valor)
                        else:
                            data[modelo].append(np.nan)

                # Configurar posición de barras
                x = np.arange(n_casos)
                width = 0.15

                # Colores para modelos
                colors = plt.cm.tab10(np.linspace(0, 1, len(modelos)))

                for i, (modelo, valores) in enumerate(data.items()):
                    offset = (i - len(modelos)/2) * width
                    bars = ax.bar(x + offset, valores, width, label=modelo, color=colors[i], alpha=0.8)

                    # Añadir valores en las barras
                    for bar, val in zip(bars, valores):
                        if not np.isnan(val):
                            height = bar.get_height()
                            ax.text(bar.get_x() + bar.get_width()/2., height + 0.01,
                                   f'{val:.3f}', ha='center', va='bottom', fontsize=8, rotation=45)

                ax.set_xlabel('Caso de Corrección', fontsize=12)
                ax.set_ylabel(metrica, fontsize=12)
                ax.set_title(f'Comparación de {metrica} entre Casos', fontsize=14, fontweight='bold')
                ax.set_xticks(x)
                ax.set_xticklabels(casos, rotation=0)
                ax.legend(loc='upper left', bbox_to_anchor=(1, 1))
                ax.grid(True, alpha=0.3)

                # Ajustar límites según métrica
                if metrica == 'R2':
                    ax.set_ylim(-0.2, 1.1)
                    ax.axhline(y=0, color='gray', linestyle='--', alpha=0.5)
                else:
                    ax.set_ylim(bottom=0)

            plt.tight_layout()
            plt.suptitle('Comparación de Métricas por Caso de Corrección de Agua',
                        fontsize=16, fontweight='bold', y=1.02)
            plt.show()

        except Exception as e:
            print(f"Error generando gráficos comparativos: {e}")

    def _recomendar_mejor_caso(self, metricas_por_caso, modelos):
        """
        Recomienda el mejor caso basado en métricas agregadas
        """
        print("\n" + "="*100)
        print(" " * 35 + "RECOMENDACIÓN DEL MEJOR CASO")
        print("="*100)

        # Calcular métrica agregada (promedio de R² y promedio inverso de RMSE)
        casos_ranking = []

        for caso_name, caso_metricas in metricas_por_caso.items():
            r2_list = []
            rmse_list = []

            for modelo in modelos:
                if modelo in caso_metricas:
                    r2 = caso_metricas[modelo].get('R2')
                    rmse = caso_metricas[modelo].get('RMSE')

                    if r2 is not None and not np.isnan(r2):
                        r2_list.append(r2)
                    if rmse is not None and not np.isnan(rmse):
                        rmse_list.append(rmse)

            if r2_list and rmse_list:
                r2_mean = np.mean(r2_list)
                rmse_mean = np.mean(rmse_list)

                # Puntuación combinada (mayor es mejor)
                score = r2_mean * 0.6 + (1 / (rmse_mean + 1e-6)) * 0.4

                casos_ranking.append({
                    'caso': caso_name,
                    'R²_medio': r2_mean,
                    'RMSE_medio': rmse_mean,
                    'score': score
                })

        # Ordenar por score
        casos_ranking.sort(key=lambda x: x['score'], reverse=True)

        # Mostrar ranking
        print("\nRanking de casos por desempeño:")
        print("-" * 80)
        print(f"{'Caso':<15} {'R² Medio':<12} {'RMSE Medio':<12} {'Score':<10}")
        print("-" * 80)

        for item in casos_ranking:
            print(f"{item['caso']:<15} {item['R²_medio']:.4f}      {item['RMSE_medio']:.4f}      {item['score']:.4f}")

        print("-" * 80)

        # Recomendación
        if casos_ranking:
            mejor_caso = casos_ranking[0]
            print(f"\n RECOMENDACIÓN: {mejor_caso['caso'].upper()} es el mejor caso")
            print(f"   • R² promedio: {mejor_caso['R²_medio']:.4f}")
            print(f"   • RMSE promedio: {mejor_caso['RMSE_medio']:.4f} m")

            # Interpretación
            if mejor_caso['R²_medio'] > 0.8:
                print("   • Calificación: EXCELENTE - Excelente precisión en la corrección")
            elif mejor_caso['R²_medio'] > 0.6:
                print("   • Calificación: BUENA - Buena precisión en la corrección")
            elif mejor_caso['R²_medio'] > 0.4:
                print("   • Calificación: MODERADA - Precisión aceptable")
            else:
                print("   • Calificación: BAJA - Considere mejorar la calidad de datos")

        # Explicación de cada caso
        print("\n" + "="*100)
        print("EXPLICACIÓN DE CASOS:")
        print("="*100)
        print("• CASO 1 (Sin corrección): Usa todos los datos sin filtrar agua clara")
        print("  - Útil cuando no se tiene información de calidad de agua")
        print("  - Puede incluir áreas turbias que afectan la precisión")
        print("\n• CASO 2 (GMM-NDCI): Filtra agua clara usando solo NDCI")
        print("  - NDCI (Normalized Difference Chlorophyll Index) detecta clorofila")
        print("  - Útil en áreas con influencia de algas")
        print("\n• CASO 3 (GMM-NDTI): Filtra agua clara usando solo NDTI")
        print("  - NDTI (Normalized Difference Turbidity Index) detecta turbidez")
        print("  - Útil en áreas con sedimentos en suspensión")
        print("\n• CASO 4 (GMM-NDCI+NDTI): Filtra usando ambos índices")
        print("  - Combinación de clorofila y turbidez")
        print("  - Generalmente produce mejor clasificación de agua clara")

# ====================================================
# EJECUCIÓN DE LOS 5 CASOS (incluyendo caso adicional)
# ====================================================

print("\n" + "="*100)
print(" " * 25 + "INICIANDO ANÁLISIS DE 5 CASOS DE CORRECCIÓN DE AGUA")
print("="*100)

# Ejecutar los 4 casos principales
analisis_casos = AnalisisCasosCorreccionAgua(CONFIG_SIMPLE)
resultados_casos = analisis_casos.ejecutar_casos()

# Mostrar comparación
analisis_casos.mostrar_comparacion_casos()

# ====================================================
# CASO 5: Caso adicional con clasificación mejorada
# ====================================================
print("\n" + "="*100)
print(" " * 35 + "CASO 5: CORRECCIÓN AVANZADA (GMM + CALIBRACIÓN BRAZA)")
print("="*100)

config_caso5 = CONFIG_SIMPLE.copy()
config_caso5['use_clear_water_only'] = True
config_caso5['clear_water_method'] = 'gmm_combined'
config_caso5['use_braza_calibration'] = True
config_caso5['braza_turbidity_threshold'] = 3.0

print("\nConfiguración del Caso 5:")
print("  • Clasificación: GMM combinado (NDCI + NDTI)")
print("  • Calibración: Con datos Braza")
print("  • Umbral de turbidez Braza: 3.0 NTU")
print("  • Filtro de agua clara: Activado")

pipeline_caso5 = SDBPipeline(config_caso5)
resultados_caso5 = pipeline_caso5.run()

# Añadir caso 5 a los resultados existentes
if 'results' in resultados_caso5 and resultados_caso5['results'] is not None:
    resultados_casos['caso_5'] = {
        'config': config_caso5,
        'results_df': resultados_caso5['results'],
        'df_comparison': resultados_caso5.get('df_comparison', None),
        'pipeline': pipeline_caso5
    }

# Mostrar comparación final con caso 5 incluido
print("\n" + "="*100)
print(" " * 30 + "COMPARACIÓN FINAL DE LOS 5 CASOS")
print("="*100)

# Actualizar metricas_por_caso para incluir caso 5
metricas_finales = {}
for caso_name, caso_data in resultados_casos.items():
    if 'error' in caso_data:
        continue
    df_results = caso_data.get('results_df')
    if df_results is not None and not df_results.empty:
        caso_metricas = {}
        for modelo in ['Lyzenga', 'Stumpf', 'RF', 'GB', 'XGB']:
            if modelo in df_results.index:
                caso_metricas[modelo] = {
                    'RMSE': df_results.loc[modelo, 'RMSE'] if 'RMSE' in df_results.columns else np.nan,
                    'MAE': df_results.loc[modelo, 'MAE'] if 'MAE' in df_results.columns else np.nan,
                    'R2': df_results.loc[modelo, 'R2'] if 'R2' in df_results.columns else np.nan
                }
        metricas_finales[caso_name] = caso_metricas

# Crear tabla comparativa final
print("\n" + "="*120)
print("TABLA COMPARATIVA DE MÉTRICAS POR CASO (INCLUYE CASO 5)")
print("="*120)

header = f"{'Modelo':<12}"
for caso in metricas_finales.keys():
    header += f" | {caso.upper():^40}"
print(header)
print("-" * (12 + 42 * len(metricas_finales)))

for modelo in ['Lyzenga', 'Stumpf', 'RF', 'GB', 'XGB']:
    row = f"{modelo:<12}"
    for caso_name, caso_metricas in metricas_finales.items():
        if modelo in caso_metricas:
            m = caso_metricas[modelo]
            rmse = m.get('RMSE', np.nan)
            mae = m.get('MAE', np.nan)
            r2 = m.get('R2', np.nan)
            if not np.isnan(rmse):
                row += f" | RMSE:{rmse:.3f} MAE:{mae:.3f} R²:{r2:.3f}"
            else:
                row += f" | {'--/--/--':^40}"
        else:
            row += f" | {'---':^40}"
    print(row)

print("\n" + "="*120)
print("LEGENDAS:")
print("  • RMSE: Raíz del Error Cuadrático Medio (menor es mejor)")
print("  • MAE: Error Absoluto Medio (menor es mejor)")
print("  • R²: Coeficiente de Determinación (mayor es mejor, máximo 1.0)")
print("\n  • CASO 1: Sin corrección de agua")
print("  • CASO 2: GMM solo con NDCI")
print("  • CASO 3: GMM solo con NDTI")
print("  • CASO 4: GMM con NDCI + NDTI")
print("  • CASO 5: GMM combinado + Calibración Braza (avanzado)")
print("="*120)

# Recomendación final
print("\n" + "="*100)
print(" " * 35 + "RECOMENDACIÓN FINAL")
print("="*100)

mejor_caso_final = None
mejor_r2_promedio = -np.inf

for caso_name, caso_metricas in metricas_finales.items():
    r2_list = []
    for modelo in ['RF', 'GB', 'XGB']:  # Considerar solo modelos ML
        if modelo in caso_metricas:
            r2 = caso_metricas[modelo].get('R2')
            if r2 is not None and not np.isnan(r2):
                r2_list.append(r2)

    if r2_list:
        r2_promedio = np.mean(r2_list)
        if r2_promedio > mejor_r2_promedio:
            mejor_r2_promedio = r2_promedio
            mejor_caso_final = caso_name

if mejor_caso_final:
    print(f"\n✅ MEJOR CASO RECOMENDADO: {mejor_caso_final.upper()}")
    print(f"   • R² promedio (RF, GB, XGB): {mejor_r2_promedio:.4f}")

    if mejor_caso_final == 'caso_5':
        print("\n   El Caso 5 (GMM combinado + Calibración Braza) demostró ser superior")
        print("   porque:")
        print("    1. Combina la clasificación de agua clara con NDCI y NDTI")
        print("    2. Utiliza datos de campo (Braza) para calibrar el modelo")
        print("    3. Mejora la estimación de turbidez y profundidad")
    elif mejor_caso_final == 'caso_4':
        print("\n   El Caso 4 (GMM con NDCI+NDTI) fue el mejor entre los casos sin calibración")
        print("   Recomendado cuando no hay datos de campo disponibles")
    elif mejor_caso_final == 'caso_3':
        print("\n   El Caso 3 (GMM solo con NDTI) fue mejor que el caso sin corrección")
        print("   Útil en áreas con alta influencia de sedimentos")
    elif mejor_caso_final == 'caso_2':
        print("\n   El Caso 2 (GMM solo con NDCI) fue mejor que el caso sin corrección")
        print("   Útil en áreas con alta influencia de algas/clorofila")
    else:
        print("\n   El Caso 1 (sin corrección) fue el mejor, indicando que")
        print("   la corrección de agua clara no fue beneficiosa para esta área")

print("\n" + "="*100)
print(" " * 40 + "ANÁLISIS COMPLETADO")
